struct TimeSignature { int numerator; int denominator; };
constexpr std::array<TimeSignature, 4> kTimeSignatures = {{
    {3, 4}, {4, 4}, {5, 4}, {7, 8}
}};
TimeSignature timeSignatureForChoice(const int choice) noexcept {
    return kTimeSignatures[static_cast<std::size_t>(juce::jlimit(1, 4, choice) - 1)];
}
int timeSignatureChoiceFor(const int numerator, const int denominator) noexcept {
    for (std::size_t index = 0; index < kTimeSignatures.size(); ++index)
        if (kTimeSignatures[index].numerator == numerator
            && kTimeSignatures[index].denominator == denominator)
            return static_cast<int>(index + 1);
    return 0;
}
constexpr bool isRotaryBassParameter(const std::size_t index) noexcept {
    return (index >= 1 && index <= 6)
        || (index >= 8 && index <= 12);
}
