BassRecipe makeDefaultBassRecipe() {
    BassRecipe recipe;
    constexpr std::array<std::uint8_t, kBassStepsPerBar> line = {
        36, 0, 36, 0, 43, 0, 36, 0, 36, 0, 39, 0, 41, 0, 43, 0,
        36, 0, 43, 0};
    for (std::size_t step = 0; step < line.size(); ++step) {
        if (line[step] == 0)
            continue;
        auto& cell = recipe.cells[step];
        cell.kind = BassCellKind::note;
        cell.midi = line[step];
        cell.durationSteps = 2;
    }
    return recipe;
}

juce::String midiPitchName(const int midi) {
    constexpr std::array<const char*, 12> pitchClasses = {
        "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"};
    const int boundedMidi = juce::jlimit(0, 127, midi);
    return juce::String(pitchClasses[static_cast<std::size_t>(boundedMidi % 12)])
        + juce::String(boundedMidi / 12 - 1);
}

// Registro de cada derivado da fonte MIDI (schema 57, 12/11/2026): fecha o
// item "completar o manifesto por célula/derivado" do TAREFAS — identificador
// do derivado, operação, parâmetros e resultado. O identificador encadeia o
// SHA-256 da fonte, o identificador anterior, a operação e o resultado: a
// mesma fonte com a mesma sequência de operações dá o mesmo identificador.
// Não verifica licença nem atribuição (isso continua com o músico).
struct MidiDerivedRecord {
    juce::String id;          // "drv-" + 16 hex
    juce::String operation;   // nome da operação, sem parâmetros
    juce::String parameters;  // o que vinha após ":" (seed, voz…)
    juce::String result;      // ataques por lane depois da operação
    bool operator==(const MidiDerivedRecord& other) const {
        return id == other.id && operation == other.operation
            && parameters == other.parameters && result == other.result;
    }
    bool operator!=(const MidiDerivedRecord& other) const { return !(*this == other); }
};

