    int diagnosticMixerViewY() const noexcept { return mixerSectionY(); }
    bool scrollActivePageByWheel(const float deltaY) {
        if (pageViewport_ == nullptr || std::abs(deltaY) < 1.0e-6f)
            return false;
        const int viewY = pageViewport_->getViewPositionY();
        const int mixerStart = juce::jmax(0,
            mixerSectionY() - pinnedHeaderHeight() - 8);
        const int bassStart = juce::jmax(0,
            bassSectionY() - pinnedHeaderHeight() - 8);
        if (viewY < mixerStart)
            return false;
        const bool bassPage = viewY >= bassStart;
        const int sectionY = bassPage ? bassSectionY() : mixerSectionY();
        const int sectionHeight = bassPage
            ? bassSectionHeight() : mixerSectionHeight();
        const int first = juce::jmax(0, sectionY - pinnedHeaderHeight() - 8);
        const int last = juce::jmax(first, sectionY + sectionHeight
            - (pageViewport_->getHeight() - kPinnedFooterHeight));
        const int step = static_cast<int>(std::lround(deltaY * 600.0f));
        pageViewport_->setViewPosition(0, juce::jlimit(first, last,
            viewY - step));
        return true;
    }
    void selectMixerVoice(const std::size_t voice) {
        if (voice >= kMaxActiveVoices)
            return;
        selectedMixerVoice_ = voice;
        updateChannelLevels();
        repaint(0, mixerSectionY(), getWidth(), mixerSectionHeight());
    }
    void selectMixerVoiceChip8ForDiagnostic() {
        const auto voice = selectedMixerVoice_;
        voiceSoundOverrides_[voice].store(static_cast<int>(SoundCharacter::chip8),
                                           std::memory_order_relaxed);
        chipDutyCycles_[voice].store(0.25f, std::memory_order_relaxed);
        chipClockHz_[voice].store(4000.0f, std::memory_order_relaxed);
        chipBitDepth_[voice].store(4, std::memory_order_relaxed);
        chipNoiseMix_[voice].store(0.60f, std::memory_order_relaxed);
        voiceSoundBoxes_[voice].setSelectedId(
            static_cast<int>(SoundCharacter::chip8) + 2,
            juce::dontSendNotification);
        updateChannelLevels();
    }
    // Diagnóstico do baixo (12/11/2026, relato do autor: "essa linha de baixo
    // que inicia é sempre a mesma"): aplica a seed como o app faz e devolve
    // as primeiras notas publicadas para o áudio, e de onde vieram.
    // diagnóstico: o MusicXML da pauta de bateria do Study para a seed corrente
    bool diagnosticDrumMusicXml(const juce::File& file) {
        return file.replaceWithText(juce::String::fromUTF8(geometryTraceView_.drumMusicXml(
            bpmSlider_.getValue(), "Batruc · bateria · diagnóstico").c_str()), false, false, "\n");
    }

    // diagnóstico: o MusicXML que a pauta exportaria para a seed corrente
    bool diagnosticBassMusicXml(const juce::File& file) {
        return bassScoreStrip_.hasScore() && file.replaceWithText(juce::String::fromUTF8(
            bassScoreStrip_.musicXml(bpmSlider_.getValue(), "Batruc · diagnóstico").c_str()),
            false, false, "\n");
    }

    juce::String diagnosticBassForSeed(const juce::String& seed) {
        seedEditor_.setText(seed, juce::dontSendNotification);
        applySeedInput();
        requestBassPerformanceRebuild();
        juce::String out = seed + (manualBassScore_ ? " manual" : "")
            + (seedBassPerformanceValid_ ? " seeded" : " NAO-SEEDED")
            + " tom=" + juce::String::fromUTF8(bassKeyTonicName(bassKeyTonic_)) + " "
            + juce::String::fromUTF8(bassKeyScaleName(bassKeyScale_))
            + " count=" + juce::String(static_cast<int>(bassDraftPerformance_.count))
            + " :";
        {
            BassAudioRenderer probe;
            const bool accepted = probe.configure(bassDraftPerformance_, 48000.0, false);
            out << (accepted ? " ACEITA" : " RECUSADA");
            if (!accepted) {   // qual evento falha
                const auto& p = bassDraftPerformance_;
                for (std::size_t i = 0; i < p.count; ++i) {
                    const auto& e = p.events[i];
                    juce::String why;
                    if (e.timeSeconds + e.durationSeconds > p.sectionSeconds + 1.0e-9) why << "passa-do-fim ";
                    if (e.pan < -0.24f || e.pan > 0.24f) why << "pan=" << e.pan << " ";
                    if (e.midi < 24 || e.midi > 60) why << "midi=" << static_cast<int>(e.midi) << " ";
                    if (i > 0 && e.timeSeconds < p.events[i - 1].timeSeconds) why << "fora-de-ordem ";
                    if (e.durationSeconds <= 0.0) why << "dur<=0 ";
                    if (e.velocity < 0.0f || e.velocity > 1.0f) why << "vel=" << e.velocity << " ";
                    if (why.isNotEmpty()) { out << " [ev" << static_cast<int>(i) << ": " << why << "t=" << e.timeSeconds << " sec=" << p.sectionSeconds << "]"; break; }
                }
            }
        }
        const auto n = juce::jmin<std::size_t>(16, bassDraftPerformance_.count);
        for (std::size_t i = 0; i < n; ++i) {
            const auto& e = bassDraftPerformance_.events[i];
            out << " " << juce::String(e.timeSeconds, 2) << "s:" << static_cast<int>(e.midi);
        }
        // a mesma seed com FRASE ligada (e de volta ao estado anterior)
        const bool previousPhrase = bassPhraseEnabled_;
        bassPhraseEnabled_ = true;
        requestBassPerformanceRebuild();
        {
            BassAudioRenderer probe;
            out << "\n  FRASE" << (bassPhraseButton_.isEnabled() ? juce::String() : utf8(" (botão apagado)"))
                << " count=" << static_cast<int>(bassDraftPerformance_.count)
                << (probe.configure(bassDraftPerformance_, 48000.0, false) ? " ACEITA" : " RECUSADA")
                << " :";
            const auto m = juce::jmin<std::size_t>(16, bassDraftPerformance_.count);
            for (std::size_t i = 0; i < m; ++i) {
                const auto& e = bassDraftPerformance_.events[i];
                out << " " << juce::String(e.timeSeconds, 2) << "s:" << static_cast<int>(e.midi);
            }
        }
        bassPhraseEnabled_ = previousPhrase;
        requestBassPerformanceRebuild();
        return out;
    }

    bool diagnosticChip8SceneRoundTrip(const juce::File& directory,
                                       juce::String& error) {
        selectMixerVoice(1);
        selectMixerVoiceChip8ForDiagnostic();
        auto scene = captureCurrentScene();
        scene.hasMidiSource = true;
        scene.midiSourceName = "gmd-metadata-diagnostic.mid";
        scene.midiSourcePath = "/fixture/gmd-metadata-diagnostic.mid";
        scene.midiSourceBars = 2;
        scene.midiSourceSha256 = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
        scene.midiSourceRightsStatus = "verified";
        scene.midiSourceLicense = "CC BY 4.0";
        scene.midiSourceAttribution = "GMD diagnostic attribution";
        scene.midiSourceVersion = "1.0.0";
        scene.midiOperationHistory = {"midi_import",
            "seeded_phrase_variation_v2:5EED2027"};
        scene.midiDerivedRecords = {
            {"drv-0123456789abcdef", "midi_import", "", "attacks=4,2,0,8,0,0,0,0 total=14"},
            {"drv-fedcba9876543210", "seeded_phrase_variation_v2", "5EED2027",
             "attacks=4,2,0,10,1,0,0,0 total=17"}};
        scene.rhythmMode = true;
        scene.generativeDepth = 0.65f;
        scene.bassPhrase = true;
        scene.percussionKey = true;
        scene.channelOrnaments[0] = true;    // ORN começa desligado (16/11/2026)
        scene.channelOrnaments[1] = false;
        scene.formalCycleCellsEnabled = {true, false, true};
        for (auto& cycle : scene.formalCycleCells)
            for (auto& phrase : cycle) { phrase = {}; phrase.enabled = true; }
        insertRhythmicCellAttack(scene.formalCycleCells[1][0], 0.5, 0.75f);
        scene.formalCycleCells[1][0].ornaments[0] = 2;   // flam (schema 62)
        insertRhythmicCellAttack(scene.formalCycleCells[6][2], 0.125, 0.4f);
        scene.midiEditorialMetadata = {true, "latin/brazilian-samba", "beat",
                                       "4-4", "test", 89};
        auto& sourceKick = scene.midiSourceCells[0];
        sourceKick.enabled = true;
        sourceKick.count = 1;
        sourceKick.positions[0] = 0.0;
        sourceKick.strengths[0] = 0.75f;
        sourceKick.midiNotes[0] = 36u;
        auto& sourceHat = scene.midiSourceCells[2];
        sourceHat.enabled = true;
        sourceHat.count = 1;
        sourceHat.positions[0] = 0.25;
        sourceHat.strengths[0] = 0.50f;
        sourceHat.midiNotes[0] = 42u;
        sourceHat.midiHatPedal[0] = 96u;
        sourceHat.midiCollisionCount[0] = 1;
        sourceHat.midiCollisionNotes[0][0] = 46u;
        sourceHat.midiCollisionStrengths[0][0] = 0.625f;
        sourceHat.midiCollisionHatPedal[0][0] = 8u;
        scene.hasSeed = true;
        scene.seed = 0x5EED2027u;
        scene.compositionVariation = 68.0;
        scene.intensityLaw = 6;
        scene.secondIntensityLaw = 2;
        scene.intensityBlend = 0.37f;
        scene.intensityAmount = 0.68f;
        scene.channelPanTrajectories[1].enabled = true;
        scene.channelPanTrajectories[1].points = {
            -0.8f, -0.4f, 0.2f, 0.7f, 0.9f, 0.3f, -0.5f, -0.9f};
        auto& manualCell = scene.rhythmicCells[4];
        manualCell.enabled = true;
        manualCell.count = 2;
        manualCell.positions[0] = 0.125;
        manualCell.positions[1] = 0.625;
        manualCell.strengths[0] = 0.77f;
        manualCell.strengths[1] = 0.35f;
        manualCell.midiNotes[0] = 48u;
        manualCell.ornaments[1] = 6;   // rulo (schema 62)
        const auto file = directory.getChildFile("chip8-scene.batruc.txt");
        if (!file.replaceWithText(sceneFileText(scene))) {
            error = utf8("Falha ao escrever cena 8-bit de diagnóstico.");
            return false;
        }
        SceneVersion restored;
        if (!parseSceneFile(file, restored, error))
            return false;
        const auto voice = selectedMixerVoice_;
        const auto close = [](const float first, const float second) {
            return std::abs(first - second) < 1.0e-5f;
        };
        if (restored.voiceSoundOverrides[voice]
                != static_cast<int>(SoundCharacter::chip8)
            || !close(restored.chipDutyCycles[voice], 0.25f)
            || !close(restored.chipClockHz[voice], 4000.0f)
            || restored.chipBitDepth[voice] != 4
            || !close(restored.chipNoiseMix[voice], 0.60f)
            || !restored.hasMidiSource
            || restored.midiSourcePath != scene.midiSourcePath
            || restored.midiSourceBars != 2
            || restored.midiSourceSha256 != scene.midiSourceSha256
            || restored.midiSourceRightsStatus != "verified"
            || restored.midiSourceLicense != "CC BY 4.0"
            || restored.midiSourceAttribution != "GMD diagnostic attribution"
            || restored.midiSourceVersion != "1.0.0"
            || restored.midiOperationHistory != scene.midiOperationHistory
            || restored.midiDerivedRecords != scene.midiDerivedRecords
            || !restored.rhythmMode
            || std::abs(restored.generativeDepth - 0.65f) > 1e-6f
            || !restored.bassPhrase
            || !restored.percussionKey
            || restored.channelOrnaments[1] || !restored.channelOrnaments[0]
            || restored.formalCycleCellsEnabled != scene.formalCycleCellsEnabled
            || restored.formalCycleCells[1][0].count != 1
            || restored.formalCycleCells[1][0].ornaments[0] != 2
            || std::abs(restored.formalCycleCells[1][0].positions[0] - 0.5) > 1e-9
            || std::abs(restored.formalCycleCells[6][2].strengths[0] - 0.4f) > 1e-6f
            || !restored.midiEditorialMetadata.present
            || restored.midiEditorialMetadata.style != "latin/brazilian-samba"
            || restored.midiEditorialMetadata.beatType != "beat"
            || restored.midiEditorialMetadata.meter != "4-4"
            || restored.midiEditorialMetadata.split != "test"
            || restored.midiEditorialMetadata.bpm != 89
            || !restored.hasSeed || restored.seed != 0x5EED2027u
            || std::abs(restored.compositionVariation - 68.0) > 1.0e-9
            || restored.intensityLaw != 6 || restored.secondIntensityLaw != 2
            || !close(restored.intensityBlend, 0.37f)
            || !close(restored.intensityAmount, 0.68f)
            || !restored.channelPanTrajectories[1].enabled
            || restored.channelPanTrajectories[1].points
                != scene.channelPanTrajectories[1].points) {
            error = utf8("Cena não preservou seed, blend, leis, pan ou metadados 8-bit.");
            return false;
        }
        if (!restored.rhythmicCells[4].enabled
            || restored.rhythmicCells[4].count != 2
            || std::abs(restored.rhythmicCells[4].positions[0] - 0.125) > 1.0e-9
            || std::abs(restored.rhythmicCells[4].positions[1] - 0.625) > 1.0e-9
            || !close(restored.rhythmicCells[4].strengths[0], 0.77f)
            || !close(restored.rhythmicCells[4].strengths[1], 0.35f)
            || restored.rhythmicCells[4].ornaments[1] != 6) {
            error = utf8("Cena não preservou a célula rítmica editada manualmente.");
            return false;
        }
        if (restored.midiSourceCells[0].count != 1
            || std::abs(restored.midiSourceCells[0].positions[0]) > 1.0e-9
            || !close(restored.midiSourceCells[0].strengths[0], 0.75f)
            || restored.midiSourceCells[0].midiNotes[0] != 36u
            || restored.midiSourceCells[2].count != 1
            || std::abs(restored.midiSourceCells[2].positions[0] - 0.25) > 1.0e-9
            || !close(restored.midiSourceCells[2].strengths[0], 0.50f)
            || restored.midiSourceCells[2].midiNotes[0] != 42u
            || restored.midiSourceCells[2].midiHatPedal[0] != 96u
            || restored.midiSourceCells[2].midiCollisionCount[0] != 1u
            || restored.midiSourceCells[2].midiCollisionNotes[0][0] != 46u
            || !close(restored.midiSourceCells[2]
                .midiCollisionStrengths[0][0], 0.625f)
            || restored.midiSourceCells[2]
                .midiCollisionHatPedal[0][0] != 8u) {
            error = utf8("Cena não preservou notas, CC4 ou ataques MIDI simultâneos.");
            return false;
        }
        if (!close(restored.bassChannelPan, scene.bassChannelPan)) {
            error = utf8("Cena não preservou o panorama do canal do baixo.");
            return false;
        }

        // schema 56: sem registro de derivados — abre, e o registro fica vazio
        auto schema56 = juce::JSON::parse(sceneFileText(scene));
        auto* schema56Root = schema56.getDynamicObject();
        auto* schema56Source = schema56Root != nullptr
            ? schema56Root->getProperty("midi_source").getDynamicObject() : nullptr;
        if (schema56Source == nullptr) {
            error = utf8("Cena schema 56 de diagnóstico inválida.");
            return false;
        }
        schema56Root->setProperty("schema_version", 56);
        schema56Source->removeProperty("derived");
        const auto schema56File = directory.getChildFile("derived-schema56.batruc.txt");
        if (!schema56File.replaceWithText(juce::JSON::toString(schema56, true))) {
            error = utf8("Falha ao escrever cena schema 56 de diagnóstico.");
            return false;
        }
        SceneVersion restoredSchema56;
        if (!parseSceneFile(schema56File, restoredSchema56, error)
            || !restoredSchema56.midiDerivedRecords.empty()
            || restoredSchema56.midiOperationHistory != scene.midiOperationHistory) {
            if (error.isEmpty())
                error = utf8("Schema 56 não abriu sem registro de derivados.");
            return false;
        }

        auto schema55 = juce::JSON::parse(sceneFileText(scene));
        auto* schema55Root = schema55.getDynamicObject();
        auto* schema55Channels = schema55Root != nullptr
            ? schema55Root->getProperty("channels").getArray() : nullptr;
        if (schema55Root == nullptr || schema55Channels == nullptr
            || schema55Channels->size() != static_cast<int>(kMaxVoices)) {
            error = utf8("Cena schema 55 de diagnóstico inválida.");
            return false;
        }
        schema55Root->setProperty("schema_version", 55);
        for (auto& channelValue : *schema55Channels) {
            auto* channel = channelValue.getDynamicObject();
            if (channel == nullptr) {
                error = utf8("Canal inválido na cena schema 55 de diagnóstico.");
                return false;
            }
            channel->removeProperty("pan_path_enabled");
            channel->removeProperty("pan_path");
        }
        const auto schema55File = directory.getChildFile(
            "pan-path-schema55.batruc.txt");
        if (!schema55File.replaceWithText(juce::JSON::toString(schema55, true))) {
            error = utf8("Falha ao escrever cena schema 55 de diagnóstico.");
            return false;
        }
        SceneVersion restoredSchema55;
        if (!parseSceneFile(schema55File, restoredSchema55, error)
            || restoredSchema55.channelPanTrajectories[1].enabled) {
            if (error.isEmpty())
                error = utf8("Schema 55 não migrou para o pan automático do campo.");
            return false;
        }

        auto legacy = juce::JSON::parse(sceneFileText(scene));
        auto* legacyRoot = legacy.getDynamicObject();
        auto* legacySource = legacyRoot != nullptr
            ? legacyRoot->getProperty("midi_source").getDynamicObject() : nullptr;
        if (legacySource == nullptr) {
            error = utf8("Cena GMD de diagnóstico não contém sua fonte MIDI.");
            return false;
        }
        legacyRoot->setProperty("schema_version", 54);
        for (const auto* property : {"editorial_metadata_present", "editorial_style",
                 "editorial_beat_type", "editorial_meter", "editorial_split",
                 "editorial_bpm"})
            legacySource->removeProperty(property);
        const auto legacyFile = directory.getChildFile(
            "gmd-metadata-schema54.batruc.txt");
        if (!legacyFile.replaceWithText(juce::JSON::toString(legacy, true))) {
            error = "Falha ao escrever cena MIDI schema 54.";
            return false;
        }
        SceneVersion restoredLegacy;
        if (!parseSceneFile(legacyFile, restoredLegacy, error)
            || restoredLegacy.midiEditorialMetadata.present
            || !restoredLegacy.hasSeed || restoredLegacy.seed != 0x5EED2027u
            || restoredLegacy.intensityLaw != 6
            || restoredLegacy.secondIntensityLaw != 2
            || !close(restoredLegacy.intensityBlend, 0.37f)
            || !close(restoredLegacy.intensityAmount, 0.68f)
            || restoredLegacy.channelPanTrajectories[1].enabled
            || !restoredLegacy.rhythmicCells[4].enabled
            || restoredLegacy.rhythmicCells[4].count != 2
            || std::abs(restoredLegacy.rhythmicCells[4].positions[0] - 0.125)
                > 1.0e-9
            || std::abs(restoredLegacy.rhythmicCells[4].positions[1] - 0.625)
                > 1.0e-9
            || !close(restoredLegacy.rhythmicCells[4].strengths[0], 0.77f)
            || !close(restoredLegacy.rhythmicCells[4].strengths[1], 0.35f)
            || restoredLegacy.midiSourceCells[2].midiHatPedal[0] != 96u
            || restoredLegacy.midiSourceCells[2].midiCollisionCount[0] != 1u
            || restoredLegacy.midiSourceCells[2].midiCollisionNotes[0][0] != 46u) {
            if (error.isEmpty())
                error = utf8("Schema 54 perdeu conteúdo antigo ou recebeu metadados editoriais novos.");
            return false;
        }

        auto schema41 = juce::JSON::parse(sceneFileText(scene));
        auto* schema41Root = schema41.getDynamicObject();
        if (schema41Root == nullptr) {
            error = utf8("Cena schema 41 de diagnóstico inválida.");
            return false;
        }
        schema41Root->setProperty("schema_version", 41);
        schema41Root->removeProperty("intensity_law_b");
        schema41Root->removeProperty("intensity_blend");
        schema41Root->removeProperty("midi_source");
        const auto schema41File = directory.getChildFile(
            "manual-cell-schema41.batruc.txt");
        if (!schema41File.replaceWithText(juce::JSON::toString(schema41, true))) {
            error = utf8("Falha ao escrever cena schema 41 de diagnóstico.");
            return false;
        }
        SceneVersion restoredSchema41;
        if (!parseSceneFile(schema41File, restoredSchema41, error)
            || restoredSchema41.hasMidiSource
            || restoredSchema41.intensityLaw != 6
            || restoredSchema41.secondIntensityLaw != 6
            || std::abs(restoredSchema41.intensityBlend) > 1.0e-6f
            || !restoredSchema41.rhythmicCells[4].enabled
            || restoredSchema41.rhythmicCells[4].count != 2
            || std::abs(restoredSchema41.rhythmicCells[4].positions[0] - 0.125)
                > 1.0e-9
            || std::abs(restoredSchema41.rhythmicCells[4].positions[1] - 0.625)
                > 1.0e-9
            || !close(restoredSchema41.rhythmicCells[4].strengths[0], 0.77f)
            || !close(restoredSchema41.rhythmicCells[4].strengths[1], 0.35f)) {
            if (error.isEmpty())
                error = utf8("Migração schema 41 perdeu célula ou aplicou blend inexistente.");
            return false;
        }

        for (const int version : {44, 45, 46, 47}) {
            auto legacyMidi = juce::JSON::parse(sceneFileText(scene));
            auto* root = legacyMidi.getDynamicObject();
            auto* source = root != nullptr
                ? root->getProperty("midi_source").getDynamicObject() : nullptr;
            if (root == nullptr || source == nullptr) {
                error = utf8("Cena MIDI legada de diagnóstico incompleta.");
                return false;
            }
            root->setProperty("schema_version", version);
            if (version < 45) {
                source->removeProperty("sha256");
                source->removeProperty("rights_status");
            }
            if (version < 46) {
                source->removeProperty("license");
                source->removeProperty("attribution");
            }
            if (version < 47) {
                source->removeProperty("version");
                source->removeProperty("operations");
            }
            for (const auto* property : {"editorial_metadata_present",
                     "editorial_style", "editorial_beat_type", "editorial_meter",
                     "editorial_split", "editorial_bpm"})
                source->removeProperty(property);

            const auto legacyMidiFile = directory.getChildFile(
                "midi-source-schema" + juce::String(version) + ".batruc.txt");
            if (!legacyMidiFile.replaceWithText(
                    juce::JSON::toString(legacyMidi, true))) {
                error = utf8("Falha ao escrever cena MIDI legada de diagnóstico.");
                return false;
            }
            SceneVersion migrated;
            if (!parseSceneFile(legacyMidiFile, migrated, error))
                return false;
            const bool expectsHash = version >= 45;
            const bool expectsLicense = version >= 46;
            const bool expectsHistory = version >= 47;
            if (!migrated.hasMidiSource
                || migrated.midiSourceName != scene.midiSourceName
                || migrated.midiSourcePath != scene.midiSourcePath
                || migrated.midiSourceBars != scene.midiSourceBars
                || migrated.midiSourceSha256
                    != (expectsHash ? scene.midiSourceSha256 : juce::String())
                || migrated.midiSourceRightsStatus
                    != (expectsHash ? scene.midiSourceRightsStatus
                                    : juce::String("unverified"))
                || migrated.midiSourceLicense
                    != (expectsLicense ? scene.midiSourceLicense : juce::String())
                || migrated.midiSourceAttribution
                    != (expectsLicense ? scene.midiSourceAttribution : juce::String())
                || migrated.midiSourceVersion
                    != (expectsHistory ? scene.midiSourceVersion : juce::String())
                || migrated.midiOperationHistory
                    != (expectsHistory ? scene.midiOperationHistory
                                       : std::vector<juce::String>{})
                || migrated.midiEditorialMetadata.present
                || migrated.midiSourceCells[2].midiNotes[0] != kNoMidiNote
                || migrated.midiSourceCells[2].midiHatPedal[0]
                    != kNoMidiControllerValue
                || migrated.midiSourceCells[2].midiCollisionCount[0] != 0u) {
                if (error.isEmpty())
                    error = utf8("Migração MIDI schema ") + juce::String(version)
                        + utf8(" perdeu ou antecipou campos de proveniência.");
                return false;
            }
        }

        auto schema48 = juce::JSON::parse(sceneFileText(scene));
        auto* schema48Root = schema48.getDynamicObject();
        if (schema48Root == nullptr) {
            error = utf8("Cena schema 48 de diagnóstico inválida.");
            return false;
        }
        schema48Root->setProperty("schema_version", 48);
        auto* schema48Source = schema48Root->getProperty("midi_source")
            .getDynamicObject();
        if (schema48Source == nullptr) {
            error = utf8("Cena schema 48 não contém a fonte MIDI.");
            return false;
        }
        for (const auto* property : {"editorial_metadata_present", "editorial_style",
                 "editorial_beat_type", "editorial_meter", "editorial_split",
                 "editorial_bpm"})
            schema48Source->removeProperty(property);
        const auto schema48File = directory.getChildFile(
            "midi-source-schema48.batruc.txt");
        if (!schema48File.replaceWithText(juce::JSON::toString(schema48, true))) {
            error = utf8("Falha ao escrever cena schema 48 de diagnóstico.");
            return false;
        }
        SceneVersion restoredSchema48;
        if (!parseSceneFile(schema48File, restoredSchema48, error)
            || restoredSchema48.midiEditorialMetadata.present
            || !restoredSchema48.hasMidiSource
            || !restoredSchema48.rhythmicCells[4].enabled
            || restoredSchema48.rhythmicCells[4].count != 2
            || restoredSchema48.rhythmicCells[4].midiNotes[0] != 48u
            || restoredSchema48.rhythmicCells[4].midiHatPedal[0]
                != kNoMidiControllerValue
            || restoredSchema48.rhythmicCells[4].midiCollisionCount[0] != 0u
            || restoredSchema48.midiSourceCells[2].midiNotes[0] != 42u
            || restoredSchema48.midiSourceCells[2].midiHatPedal[0]
                != kNoMidiControllerValue
            || restoredSchema48.midiSourceCells[2].midiCollisionCount[0] != 0u
            || restoredSchema48.intensityLaw != 6
            || restoredSchema48.secondIntensityLaw != 2
            || !close(restoredSchema48.intensityBlend, 0.37f)) {
            if (error.isEmpty())
                error = utf8("Migração schema 48 perdeu notas ou antecipou CC4/colisões/metadados.");
            return false;
        }

        auto schema52 = juce::JSON::parse(sceneFileText(scene));
        auto* schema52Root = schema52.getDynamicObject();
        if (schema52Root == nullptr) {
            error = utf8("Cena schema 52 de diagnóstico inválida.");
            return false;
        }
        schema52Root->setProperty("schema_version", 52);
        auto* schema52Source = schema52Root->getProperty("midi_source")
            .getDynamicObject();
        if (schema52Source == nullptr) {
            error = utf8("Cena schema 52 não contém a fonte MIDI.");
            return false;
        }
        for (const auto* property : {"editorial_metadata_present", "editorial_style",
                 "editorial_beat_type", "editorial_meter", "editorial_split",
                 "editorial_bpm"})
            schema52Source->removeProperty(property);
        const auto schema52File = directory.getChildFile(
            "midi-source-schema52.batruc.txt");
        if (!schema52File.replaceWithText(juce::JSON::toString(schema52, true))) {
            error = utf8("Falha ao escrever cena schema 52 de diagnóstico.");
            return false;
        }
        SceneVersion restoredSchema52;
        if (!parseSceneFile(schema52File, restoredSchema52, error)
            || restoredSchema52.midiEditorialMetadata.present
            || !restoredSchema52.hasMidiSource
            || restoredSchema52.midiSourceCells[2].midiNotes[0] != 42u
            || restoredSchema52.midiSourceCells[2].midiHatPedal[0] != 96u
            || restoredSchema52.midiSourceCells[2].midiCollisionCount[0] != 0u
            || restoredSchema52.rhythmicCells[4].midiNotes[0] != 48u
            || restoredSchema52.rhythmicCells[4].midiHatPedal[0]
                != kNoMidiControllerValue
            || restoredSchema52.rhythmicCells[4].midiCollisionCount[0] != 0u) {
            if (error.isEmpty())
                error = utf8("Migração schema 52 perdeu CC4 ou antecipou colisões/metadados.");
            return false;
        }
        return true;
    }
    void updateChip8Inspector() {
        if (!chipControlsReady_)
            return;
        bool visibilityChanged = false;
        for (std::size_t voice = 0; voice < kMaxActiveVoices; ++voice) {
            const int overrideSound = voiceSoundOverrides_[voice].load(
                std::memory_order_relaxed);
            const int effectiveSound = overrideSound < 0
                ? juce::jlimit(0, 17, soundCharacter_.load(std::memory_order_relaxed))
                : overrideSound;
            const bool visible = effectiveSound == static_cast<int>(SoundCharacter::chip8);
            auto& sliders = chipParameterSliders_[voice];
            sliders[0].setValue(chipDutyCycles_[voice].load(std::memory_order_relaxed)
                                    * 100.0, juce::dontSendNotification);
            sliders[1].setValue(chipClockHz_[voice].load(std::memory_order_relaxed)
                                    / 1000.0, juce::dontSendNotification);
            sliders[2].setValue(chipBitDepth_[voice].load(std::memory_order_relaxed),
                                juce::dontSendNotification);
            sliders[3].setValue(chipNoiseMix_[voice].load(std::memory_order_relaxed)
                                    * 100.0, juce::dontSendNotification);
            visibilityChanged |= sliders[0].isVisible() != visible;
            for (auto& label : chipParameterLabels_[voice])
                label.setVisible(visible);
            for (auto& slider : sliders)
                slider.setVisible(visible);
        }
        if (visibilityChanged && pageViewport_ != nullptr) {
            const int height = contentHeightForWidth(getWidth());
            if (getHeight() != height)
                setSize(getWidth(), height);
            else
                resized();
        }
    }
    int diagnosticMixerOverlapCount(juce::String& details) {
        std::vector<juce::Rectangle<int>> visibleBounds;
        forEachMixerControl([&](juce::Component& component) {
            if (component.isVisible() && !component.getBounds().isEmpty())
                visibleBounds.push_back(component.getBounds());
        });
        int overlaps = 0;
        for (std::size_t first = 0; first < visibleBounds.size(); ++first)
            for (std::size_t second = first + 1;
                 second < visibleBounds.size(); ++second)
                if (visibleBounds[first].intersects(visibleBounds[second])) {
                    details += juce::String(static_cast<int>(first)) + ":"
                        + visibleBounds[first].toString() + " & "
                        + juce::String(static_cast<int>(second)) + ":"
                        + visibleBounds[second].toString() + ";";
                    ++overlaps;
                }
        return overlaps;
    }
