    // Cabeçalho (12/11/2026): o botão do modo RITMO/GERATIVO entra no início;
    // larguras recalculadas para caber da logo (até x = 243) à borda direita
    // em 1080 px. A mesma origem vale para o rótulo VOZES (headerControlsX).
    static int headerControlsX(const int width) noexcept {
        return juce::jmax(248, width - 832);
    }

    // 14/11/2026: as larguras acima eram fixas para o português em 1080 px;
    // em espanhol e francês os rótulos saíam cortados ("Mezcla…", "Apprend…")
    // ou com letra miúda. Agora cada botão mede o próprio texto, e o bloco se
    // alinha à direita; se não couber, volta às larguras fixas.
    void layoutHeaderControls(const int viewY) {
        const int y = viewY + topControlsY();
        struct Slot { juce::Component* component; int base; int gapAfter; };
        std::array<Slot, 11> slots = {{
            {&compositionModeButton_, 82, 6}, {&editorButton_, 68, 6},
            {&mixerButton_, 62, 6}, {&bassButton_, 60, 9}, {&seedEditor_, 84, 6},
            {&newSeedButton_, 82, 6}, {&voiceCountBox_, 54, 6},
            {&scenesButton_, 56, 6}, {&aboutButton_, 50, 6},
            {&learnButton_, 68, 6}, {&languageBox_, 96, 0}}};
        const auto font = monoFont(14.0f).withHeight(26.0f * 0.6f);
        std::array<int, 11> widths{};
        int fitted = 0, fixed = 0;
        for (std::size_t i = 0; i < slots.size(); ++i) {
            int width = slots[i].base;
            if (auto* button = dynamic_cast<juce::TextButton*>(slots[i].component))
                width = juce::jmax(width, juce::GlyphArrangement::getStringWidthInt(
                    font, button->getButtonText()) + 20);
            widths[i] = width;
            fitted += width + slots[i].gapAfter;
            fixed += slots[i].base + slots[i].gapAfter;
        }
        const bool fits = getWidth() - fitted - 7 >= 248;
        int x = fits ? getWidth() - fitted - 7 : headerControlsX(getWidth());
        for (std::size_t i = 0; i < slots.size(); ++i) {
            const int width = fits ? widths[i] : slots[i].base;
            slots[i].component->setBounds(x, y, width, 26);
            x += width + slots[i].gapAfter;
        }
        juce::ignoreUnused(fixed);
    }

    void updateNavigationButtons(const int viewY) {
        const int visibleHeight = pageViewport_ != nullptr
            ? pageViewport_->getHeight() : kPerformancePageHeight;
        const int focusY = viewY + visibleHeight / 2;
        const bool bass = focusY >= bassSectionY();
        const bool mixer = !bass && focusY >= mixerSectionY();
        editorButton_.setToggleState(!mixer && !bass,
                                     juce::dontSendNotification);
        mixerButton_.setToggleState(mixer, juce::dontSendNotification);
        bassButton_.setToggleState(bass, juce::dontSendNotification);
    }

    void updatePinnedChrome(const juce::Rectangle<int>& visibleArea) {
        const int viewY = pageViewport_ != nullptr
            ? pageViewport_->getViewPositionY() : 0;
        const int viewHeight = pageViewport_ != nullptr
            ? juce::jmax(0, visibleArea.getHeight()) : getHeight();
        headerChrome_.setLanguage(language_);
        bassScoreStrip_.setLanguage(language_);
        headerChrome_.setVoiceLabelY(topControlsY() - 17);
        headerChrome_.setBounds(0, viewY, getWidth(), pinnedHeaderHeight());
        layoutHeaderControls(viewY);
        headerChrome_.setVoiceLabelX(voiceCountBox_.getX());
        headerChrome_.repaint();
        updateNavigationButtons(viewY);

        if (viewHeight <= 0)
            return;
        const int footerTop = viewY + viewHeight - kPinnedFooterHeight;
        footerChrome_.setBounds(0, footerTop, getWidth(), kPinnedFooterHeight);
        playButton_.setBounds(28, footerTop, 92, 36);
        formPlaybackButton_.setBounds(126, footerTop + 4, 28, 28);
        recipeBox_.setBounds(160, footerTop, 190, 36);
        patternBox_.setBounds(360, footerTop, 190, 36);
        recordButton_.setBounds(560, footerTop + 4, 112, 28);
        recordLimitBox_.setBounds(680, footerTop + 4, 78, 28);   // "5 min" sem "…"
        geometryButton_.setBounds(766, footerTop + 4, 72, 28);
        volumeSlider_.setBounds(848, footerTop + 2, 136, 32);
        generativeDepthSlider_.setBounds(990, footerTop + 4, 80, 28);
        masterMeterLabel_.setBounds(500, footerTop + 37, 544, 18);
        if (getWidth() < 1280)
            statusLabel_.setBounds(28, footerTop + 37, 460, 18);
        else
            statusLabel_.setBounds(1080, footerTop, getWidth() - 1108, 36);
        creditLabel_.setBounds(28, footerTop + 61, getWidth() - 230, 16);
        cpuMeterLabel_.setBounds(getWidth() - 190, footerTop + 61, 162, 16);
        bringPinnedControlsForward();
    }

    void bringPinnedControlsForward() {
        // Geometry children are promoted while resizing; restore the pinned
        // chrome layer whenever the viewport scrolls.
        headerChrome_.toFront(false);
        footerChrome_.toFront(false);
        for (auto* component : std::array<juce::Component*, 23>{
                 &compositionModeButton_,
                 &voiceCountBox_, &seedEditor_, &newSeedButton_, &editorButton_,
                 &mixerButton_,
                 &scenesButton_, &aboutButton_, &learnButton_, &languageBox_,
                 &playButton_, &formPlaybackButton_, &recipeBox_, &patternBox_,
                 &bassButton_, &recordButton_, &recordLimitBox_,
                 &geometryButton_, &volumeSlider_, &generativeDepthSlider_,
                 &masterMeterLabel_, &statusLabel_, &creditLabel_})
            component->toFront(false);
        cpuMeterLabel_.toFront(false);
    }

    template <typename Fn>
    void forEachMixerControl(Fn&& apply) {
        for (juce::Component* component : std::initializer_list<juce::Component*>{
                 &soundFamilyLabel_, &soundFamilyBox_,
                 &soundCharacterLabel_, &soundCharacterBox_, &decayLabel_, &decaySlider_,
                 &fundamentalLabel_, &fundamentalSlider_, &voiceTwoTravelLabel_,
                 &voiceTwoTravelSlider_, &formulaBusGainLabel_, &formulaBusGainSlider_,
                 &mixerAutoBalanceButton_, &formulaPreviewLabel_, &polyrhythmLabel_,
                 &polyrhythmPresetBox_, &polyrhythmApplyButton_,
                 &manualCompositionButton_, &percussionKeyButton_, &bassMixerEnableButton_,
                 &bassMixerMuteButton_, &bassMixerSoloButton_,
                 &bassMixerLevelLabel_, &bassMixerLevelSlider_,
                 &bassMixerPanLabel_, &bassMixerPanSlider_})
            apply(*component);
        for (auto& voiceLabels : chipParameterLabels_)
            for (auto& label : voiceLabels)
                apply(label);
        for (auto& voiceSliders : chipParameterSliders_)
            for (auto& slider : voiceSliders)
                apply(slider);
        for (std::size_t voice = 0; voice < kMaxVoices; ++voice)
            for (juce::Component* component : std::initializer_list<juce::Component*>{
                     &mixerVoiceSelectButtons_[voice], &channelLabels_[voice],
                     &channelSliders_[voice],
                     &channelPanLabels_[voice], &channelPanSliders_[voice],
                     &channelPanMotionLabels_[voice],
                     &channelPanMotionSliders_[voice],
                     &channelPanTrajectoryEditors_[voice],
                     &channelVariationLabels_[voice],
                     &channelVariationSliders_[voice], &voiceTransformBoxes_[voice],
                     &voiceSoundBoxes_[voice], &voiceCouplingSliders_[voice],
                     &formulaPhaseLabels_[voice], &formulaPhaseOffsetSliders_[voice],
                     &voiceCycleLabels_[voice], &voiceCycleSliders_[voice],
                     &voiceRhythmPhaseLabels_[voice], &voiceRhythmPhaseSliders_[voice],
                     &voiceEventRuleBoxes_[voice], &muteButtons_[voice],
                     &ornamentButtons_[voice],
                     &soloButtons_[voice]})
                apply(*component);
    }

