    bool hasInlineGeometryLayout() const noexcept {
        return getWidth() >= kInlineGeometryMinimumWidth;
    }

    int geometrySelectorGutter(const int chartWidth) const noexcept {
        // Three columns: geometry/cells, the larger Study chart, linked view.
        return juce::jlimit(180, 300,
            static_cast<int>(std::lround(chartWidth * 0.25)));
    }

    int geometrySectionHeight() const noexcept {
        return hasInlineGeometryLayout()
            ? 0 : kGeometryBenchHeight + kNarrowGeometryPathHeight;
    }

    int mixerSectionY() const noexcept {
        return kGeometrySectionY + performanceVerticalExpansion()
            + geometrySectionHeight() + kGeometryToMixerGap;
    }

    int bassSectionY() const noexcept {
        return mixerSectionY() + mixerSectionHeight() + kMixerToBassGap;
    }

    bool isViewportRectangleVisible(const juce::Rectangle<int> bounds) const {
        if (pageViewport_ == nullptr)
            return true;
        const auto visibleArea = pageViewport_->getViewArea();
        return !visibleArea.isEmpty() && visibleArea.intersects(bounds);
    }

