    void showInlineControls() {
        forEachMixerControl([](juce::Component& component) {
            component.setVisible(true);
        });
        forEachBassControl([](juce::Component& component) {
            component.setVisible(true);
        });
        forEachGeometryControl([](juce::Component& component) {
            component.setVisible(true);
        });
        updateChannelLevels();
        updateBassEditorControls();
        updateGeometryPanelMode();
    }

    void updateBassPathLabel() {
        if ((!hasCurrentSeed_ && !hasMidiSource_) || manualBassScore_) {
            bassPathLabel_.setText(localized(language_,
                "PERCURSO · edição manual", "PATH · manual edit",
                "PARCOURS · édition manuelle"), juce::dontSendNotification);
            bassPathLabel_.setTooltip({});
            return;
        }
        juce::String details = localized(language_, "Percurso de altura",
                                          "Pitch path", "Parcours de hauteur");
        details += "   I[n]=clamp(" + juce::String(bassRecipe_.pathMemory, 2)
            + "I[n-1]+y-x, -1.5, +1.5)   R="
            + juce::String(bassRecipe_.pathBreath, 2);
        juce::String summary;
        for (std::size_t cycle = 0; cycle < bassPitchPath_.size(); ++cycle)
            summary += (cycle == 0 ? juce::String{} : juce::String("  "))
                + "C" + juce::String(static_cast<int>(cycle + 1))
                + (bassPitchPath_[cycle] >= 0 ? "+" : "")
                + juce::String(bassPitchPath_[cycle]);
        details += "   " + summary;
        const auto key = bassKeyText();
        if (key.isNotEmpty()) {
            details = key + "   " + details;
            summary = key + "  " + summary;
        }
        bassPathLabel_.setTooltip(details);
        bassPathLabel_.setText(summary, juce::dontSendNotification);
    }

    // O tom da seed, na língua da interface (12/11/2026).
    juce::String bassKeyText() const {
        if (bassKeyTonic_ < 0 || bassKeyTonic_ > 11)
            return {};
        static constexpr const char* kLetters[12] = {
            "C", "C#", "D", "Eb", "E", "F", "F#", "G", "Ab", "A", "Bb", "B"};
        static constexpr const char* kModesEn[kBassKeyScaleCount] = {
            "major", "minor", "Dorian", "Mixolydian", "Phrygian", "Lydian",
            "harmonic minor", "major pentatonic", "minor pentatonic", "blues"};
        static constexpr const char* kModesFr[kBassKeyScaleCount] = {
            "majeur", "mineur", "dorien", "mixolydien", "phrygien", "lydien",
            "mineur harmonique", "pentatonique majeure", "pentatonique mineure", "blues"};
        static constexpr const char* kModesEs[kBassKeyScaleCount] = {
            "mayor", "menor", "dórico", "mixolidio", "frigio", "lidio",
            "menor armónica", "pentatónica mayor", "pentatónica menor", "blues"};
        const auto scale = static_cast<std::size_t>(juce::jlimit(0, kBassKeyScaleCount - 1, bassKeyScale_));
        switch (language_) {
            case UiLanguage::portuguese:
                return "TOM " + juce::String::fromUTF8(bassKeyTonicName(bassKeyTonic_)) + " "
                    + juce::String::fromUTF8(bassKeyScaleName(bassKeyScale_));
            case UiLanguage::english:
                return juce::String("KEY ") + kLetters[bassKeyTonic_] + " " + kModesEn[scale];
            case UiLanguage::french:
                return juce::String("TON ") + kLetters[bassKeyTonic_] + " " + kModesFr[scale];
            case UiLanguage::spanish:
            default:
                return juce::String("TONO ") + kLetters[bassKeyTonic_] + " "
                    + juce::String::fromUTF8(kModesEs[scale]);
        }
    }

    void updateBassPathView() {
        const auto activeCycle = static_cast<std::size_t>(
            (renderer_.completedBars() / 4u) % kFormalCycleCount);
        const bool recombined = bassCycleRecombined_ && hasCurrentSeed_
            && seedBassPerformanceValid_;
        const auto donorOffset = recombined
            ? 1u + static_cast<std::size_t>(currentSeed_
                % static_cast<std::uint32_t>(kFormalCycleCount - 1))
            : 0u;
        bassPathView_.setState(bassPitchPath_, seedBassPerformance_.pathIntegral,
            seedBassPerformance_.pathDerivative,
            seedBassPerformance_.pathCorrelation,
            seedBassPerformance_.pathRegressionYFromX,
            seedBassPerformance_.pathSpeed,
            seedBassPerformance_.pathSignedCurvature,
            seedBassPerformance_.pathDensity, seedBassPerformance_.pathRoute,
            activeCycle, bassRecipe_.pathMemory, bassRecipe_.pathBreath,
            (hasCurrentSeed_ || hasMidiSource_) && !manualBassScore_
                && seedBassPerformanceValid_, language_, bassPublishedPerformance_,
            bassLogisticDynamics_, recombined, donorOffset);
    }

    int calculatedBassMidiForStep(const std::size_t step) const noexcept {
        if (step >= bassRecipe_.cells.size()
            || bassRecipe_.cells[step].kind != BassCellKind::note)
            return step < bassRecipe_.cells.size() ? bassRecipe_.cells[step].midi : 36;
        BassScore score;
        if (buildBassScore(bassRecipe_, score) != BassError::none)
            return bassRecipe_.cells[step].midi;
        for (std::size_t note = 0; note < score.count; ++note)
            if (score.notes[note].bar == 0 && score.notes[note].step == step)
                return score.notes[note].calculatedMidi;
        return bassRecipe_.cells[step].midi;
    }

    void updateBassEditorControls() {
        updateBassPathLabel();
        updateBassPathView();
        bassCycleRecombinationButton_.setEnabled(
            (hasCurrentSeed_ || hasMidiSource_) && seedBassPerformanceValid_);
        bassPhraseButton_.setEnabled(hasCurrentSeed_ && !hasMidiSource_
            && formalCycleCellsEnabled_[0]);
        const auto activeSteps = bassStepsPerBar(bassRecipe_.meterNumerator,
                                                 bassRecipe_.meterDenominator);
        std::array<std::uint8_t, kBassStepsPerBar> visibleDurations{};
        std::array<std::uint8_t, kBassStepsPerBar> calculatedPitches{};
        for (std::size_t step = 0; step < kBassStepsPerBar; ++step) {
            visibleDurations[step] = bassRecipe_.cells[step].durationSteps;
            calculatedPitches[step] = bassRecipe_.cells[step].midi;
        }
        BassScore displayScore;
        if (buildBassScore(bassRecipe_, displayScore) == BassError::none)
            for (std::size_t note = 0; note < displayScore.count; ++note) {
                if (displayScore.notes[note].bar == 0) {
                    visibleDurations[displayScore.notes[note].step] =
                        displayScore.notes[note].durationSteps;
                    calculatedPitches[displayScore.notes[note].step] =
                        displayScore.notes[note].calculatedMidi;
                }
            }
        for (std::size_t step = 0; step < bassStepButtons_.size(); ++step) {
            bassStepButtons_[step].setVisible(step < activeSteps);
            const bool active = bassRecipe_.cells[step].kind == BassCellKind::note;
            bassStepButtons_[step].setToggleState(active, juce::dontSendNotification);
            bassStepButtons_[step].setButtonText(juce::String(static_cast<int>(step + 1))
                + utf8(bassRecipe_.cells[step].kind == BassCellKind::rest ? " · R" : ""));
            bassStepButtons_[step].setColour(juce::TextButton::buttonColourId,
                active ? colour(palette::voiceOne)
                    : bassRecipe_.cells[step].kind == BassCellKind::rest
                        ? colour(palette::soft) : colour(palette::white));
            bassStepButtons_[step].setColour(juce::TextButton::textColourOffId,
                active ? colour(palette::white) : colour(palette::ink));
        }
        const bool durationEditable = bassRecipe_.durationLaw == BassDurationLaw::manual;
        bassPianoRoll_.setState(bassRecipe_.cells, visibleDurations, calculatedPitches,
                                activeSteps, bassSelectedStep_, durationEditable, language_);
        const auto& cell = bassRecipe_.cells[bassSelectedStep_];
        const int calculatedMidi = calculatedPitches[bassSelectedStep_];
        bassPitchLabel_.setText(localized(language_, "PASSO", "STEP", "PAS") + " "
            + juce::String(static_cast<int>(bassSelectedStep_ + 1)) + utf8(" · ")
            + (cell.kind == BassCellKind::note
                ? midiPitchName(cell.midi) + (calculatedMidi != cell.midi
                    ? utf8(" → ") + midiPitchName(calculatedMidi) : juce::String{})
                    + " (MIDI " + juce::String(calculatedMidi) + ")"
                : cell.kind == BassCellKind::rest
                    ? localized(language_, "PAUSA", "REST", "SILENCE")
                    : localized(language_, "VAZIO", "EMPTY", "VIDE")),
            juce::dontSendNotification);
        bassPitchSlider_.setValue(cell.kind == BassCellKind::note ? cell.midi : 36,
                                  juce::dontSendNotification);
        bassPitchSlider_.setEnabled(cell.kind == BassCellKind::note);
        bassDurationBox_.setEnabled(cell.kind == BassCellKind::note && durationEditable);
        bassRepeatsBox_.setEnabled(cell.kind == BassCellKind::note);
        bassIntentBox_.setEnabled(cell.kind == BassCellKind::note);
        bassDurationBox_.setSelectedId(cell.durationSteps, juce::dontSendNotification);
        bassRepeatsBox_.setSelectedId(cell.repeats, juce::dontSendNotification);
        bassIntentBox_.setSelectedId(static_cast<int>(cell.intent) + 1,
                                     juce::dontSendNotification);
        bassDurationLawBox_.setSelectedId(static_cast<int>(bassRecipe_.durationLaw) + 1,
                                          juce::dontSendNotification);
        constexpr std::array<double, 4> ratios = {1.2, 1.5, 1.618, 2.0};
        int ratioChoice = 2;
        for (std::size_t i = 0; i < ratios.size(); ++i)
            if (std::abs(bassRecipe_.geometricRatio - ratios[i]) < 0.002)
                ratioChoice = static_cast<int>(i + 1);
        bassGeoRatioBox_.setSelectedId(ratioChoice, juce::dontSendNotification);
        bassGeoRatioBox_.setEnabled(bassRecipe_.durationLaw == BassDurationLaw::geometric);
        bassPhraseModeBox_.setSelectedId(static_cast<int>(bassRecipe_.phraseMode) + 1,
                                         juce::dontSendNotification);
        bassRhythmRelationBox_.setSelectedId(static_cast<int>(bassRhythmRelation_) + 1,
                                             juce::dontSendNotification);
        bassLfoView_.setState(bassRecipe_.lfoEnabled, bassRecipe_.lfoShape,
            bassRecipe_.lfoPeriodCycles, bassRecipe_.lfoDepthSemitones,
            bassRecipe_.lfoTarget,
            static_cast<double>(renderer_.completedBars()) / 4.0
                + renderer_.sectionProgress(), cell.midi, calculatedMidi,
            cell.kind == BassCellKind::note, language_);
        bassPitchVariationSlider_.setValue(bassRecipe_.pitchVariation * 100.0,
                                           juce::dontSendNotification);
        if (!bassSeedEditor_.hasKeyboardFocus(true))
            bassSeedEditor_.setText(seedText(bassRecipe_.seed),
                                    juce::dontSendNotification);
        bassVariationLevelBox_.setSelectedId(
            static_cast<int>(bassRecipe_.variationLevel) + 1,
            juce::dontSendNotification);
        bassPathMemorySlider_.setValue(bassRecipe_.pathMemory * 100.0,
                                       juce::dontSendNotification);
        bassPathBreathSlider_.setValue(bassRecipe_.pathBreath * 100.0,
                                       juce::dontSendNotification);
    }

