    void requestBassPerformanceRebuild() {
        if ((hasCurrentSeed_ || hasMidiSource_) && !manualBassScore_)
            generateSeedBassLineFromVoicePlan();
        bassRecipe_.bpm = bpmSlider_.getValue();
        const auto signature = timeSignatureForChoice(meterBox_.getSelectedId());
        bassRecipe_.meterNumerator = static_cast<std::uint8_t>(signature.numerator);
        bassRecipe_.meterDenominator = static_cast<std::uint8_t>(signature.denominator);
        BassScore score;
        BassInterpretation interpretation;
        interpretation.velocity = 0.70f;
        const float globalSwing = static_cast<float>(juce::jmax(0.0,
            (swingSlider_.getValue() / 100.0 - 0.5) * 4.0));
        interpretation.swing = juce::jmin(0.67f, juce::jmax(globalSwing,
            static_cast<float>(bassSwingSlider_.getValue() / 100.0)));
        BassPerformance performance;
        if ((hasCurrentSeed_ || hasMidiSource_) && seedBassPerformanceValid_) {
            const bool voiceDerivedSeed = std::any_of(
                seedBassPerformance_.events.begin(),
                seedBassPerformance_.events.begin()
                    + static_cast<std::ptrdiff_t>(seedBassPerformance_.count),
                [](const BassPlayedEvent& event) {
                    return event.formCycle < kFormalCycleCount;
                });
            performance = seedBassPerformance_;
            const auto stepsPerBar = bassStepsPerBar(
                bassRecipe_.meterNumerator, bassRecipe_.meterDenominator);
            const double stepSeconds = performance.sectionSeconds
                / static_cast<double>(kBassBarsPerSection * stepsPerBar);
            const double barSeconds = stepSeconds * stepsPerBar;
            const float seededSwing = juce::jmin(0.67f, juce::jmax(globalSwing,
                static_cast<float>(bassSwingSlider_.getValue() / 100.0)));
            std::uint32_t pitchState = bassRecipe_.seed ^ 0xB455F00Du;
            std::size_t kept = 0;
            for (std::size_t index = 0; index < performance.count; ++index) {
                auto event = performance.events[index];
                const auto bar = static_cast<std::size_t>(event.timeSeconds / barSeconds);
                const auto step = static_cast<std::size_t>(
                    std::fmod(event.timeSeconds, barSeconds) / stepSeconds);
                const bool phraseRest = bassRecipe_.phraseMode == BassPhraseMode::breath
                        ? bar % 2 == 1 && step >= stepsPerBar - 2
                    : bassRecipe_.phraseMode == BassPhraseMode::cadence
                        ? bar % 4 == 3 && step >= stepsPerBar - 4
                    : bassRecipe_.phraseMode == BassPhraseMode::callResponse
                        ? bar % 2 == 1 : false;
                if (phraseRest && event.formCycle >= kFormalCycleCount)
                    continue;

                if (!voiceDerivedSeed
                    && bassRhythmRelation_ == BassRhythmRelation::independent)
                    event.timeSeconds = std::floor(event.timeSeconds / stepSeconds)
                        * stepSeconds;
                if (!voiceDerivedSeed && seededSwing > 0.0f && step % 2 == 1)
                    event.timeSeconds = std::min(performance.sectionSeconds - 0.001,
                        event.timeSeconds + seededSwing * stepSeconds);
                if (!voiceDerivedSeed) {
                    const float pitchChance = static_cast<float>(compositionSeedRandom(pitchState));
                    const int pitchRadius = static_cast<int>(std::lround(
                        6.0f * bassRecipe_.pitchVariation));
                    if (pitchRadius > 0 && pitchChance < bassRecipe_.pitchVariation) {
                        const int offset = static_cast<int>(std::floor(
                            compositionSeedRandom(pitchState) * (2 * pitchRadius + 1)))
                            - pitchRadius;
                        event.midi = static_cast<std::uint8_t>(juce::jlimit(24, 60,
                            static_cast<int>(event.midi) + offset));
                    }
                }
                if (!voiceDerivedSeed) switch (bassRecipe_.durationLaw) {
                    case BassDurationLaw::manual:
                        event.durationSeconds = 2.0 * stepSeconds;
                        break;
                    case BassDurationLaw::fibonacci: {
                        constexpr std::array<int, 8> durations =
                            {1, 1, 2, 3, 5, 8, 13, 16};
                        event.durationSeconds = std::min<double>(stepsPerBar,
                            durations[kept % durations.size()]) * stepSeconds;
                        break;
                    }
                    case BassDurationLaw::geometric:
                        event.durationSeconds = juce::jlimit(1.0,
                            static_cast<double>(stepsPerBar),
                            std::pow(bassRecipe_.geometricRatio,
                                static_cast<double>(kept % 8))) * stepSeconds;
                        break;
                }
                performance.events[kept++] = event;
            }
            performance.count = kept;
            // Make a new seed audible in the opening phrase, where following
            // the same percussion anchors otherwise makes successive bass
            // lines begin identically. Add one quiet, seed-selected answer
            // on a free offbeat of bar one; never replace a source attack.
            if (voiceDerivedSeed && bassRecipe_.variationLevel > 0
                && performance.count < performance.events.size()) {
                const auto pulseSteps = std::max<std::size_t>(1,
                    16u / bassRecipe_.meterDenominator);
                const auto offbeatInPulse = std::max<std::size_t>(1,
                    pulseSteps / 2);
                std::array<std::size_t, kBassStepsPerBar> openingCandidates{};
                std::size_t openingCandidateCount = 0;
                for (std::size_t step = 0; step < stepsPerBar; ++step) {
                    if (step % pulseSteps != offbeatInPulse)
                        continue;
                    const double time = static_cast<double>(step) * stepSeconds;
                    const bool occupied = std::any_of(performance.events.begin(),
                        performance.events.begin()
                            + static_cast<std::ptrdiff_t>(performance.count),
                        [time, stepSeconds](const BassPlayedEvent& event) {
                            return event.formCycle == 0
                                && std::abs(event.timeSeconds - time)
                                    < stepSeconds * 0.2;
                        });
                    if (!occupied)
                        openingCandidates[openingCandidateCount++] = step;
                }
                std::size_t donor = performance.count;
                double donorDistance = std::numeric_limits<double>::infinity();
                for (std::size_t index = 0; index < performance.count; ++index) {
                    const auto& event = performance.events[index];
                    if (event.formCycle != 0 || event.timeSeconds >= barSeconds)
                        continue;
                    const double distance = std::abs(event.timeSeconds);
                    if (distance < donorDistance) {
                        donor = index;
                        donorDistance = distance;
                    }
                }
                if (openingCandidateCount > 0 && donor < performance.count) {
                    std::uint32_t openingSeed = bassCompositionSeed(
                        bassRecipe_.seed, currentSeed_) ^ 0x4F50454Eu;
                    const auto candidateIndex = static_cast<std::size_t>(
                        compositionSeedRandom(openingSeed)
                            * static_cast<double>(openingCandidateCount));
                    constexpr std::array<int, 7> openingPitchShifts =
                        {-5, -3, -2, 0, 2, 3, 5};
                    const auto pitchIndex = static_cast<std::size_t>(
                        compositionSeedRandom(openingSeed)
                            * static_cast<double>(openingPitchShifts.size()));
                    auto answer = performance.events[donor];
                    const auto step = openingCandidates[std::min(
                        candidateIndex, openingCandidateCount - 1)];
                    answer.timeSeconds = static_cast<double>(step) * stepSeconds;
                    answer.durationSeconds = 0.5 * stepSeconds;
                    answer.midi = static_cast<std::uint8_t>(juce::jlimit(24, 60,
                        static_cast<int>(answer.midi) + openingPitchShifts[
                            std::min(pitchIndex, openingPitchShifts.size() - 1)]));
                    answer.velocity *= bassRecipe_.variationLevel == 1 ? 0.16f
                        : bassRecipe_.variationLevel == 2 ? 0.22f : 0.28f;
                    answer.sourceNote = static_cast<std::uint16_t>(step);
                    answer.formCycle = 0;
                    performance.events[performance.count++] = answer;
                }
            }
            std::sort(performance.events.begin(),
                performance.events.begin() + static_cast<std::ptrdiff_t>(performance.count),
                [](const BassPlayedEvent& a, const BassPlayedEvent& b) {
                    return a.timeSeconds < b.timeSeconds;
                });
            std::size_t uniqueCount = 0;
            for (std::size_t index = 0; index < performance.count; ++index) {
                const auto event = performance.events[index];
                if (uniqueCount > 0
                    && bassEventsCollideWithinSameCycle(
                        performance.events[uniqueCount - 1], event, stepSeconds * 0.2)) {
                    if (event.velocity > performance.events[uniqueCount - 1].velocity)
                        performance.events[uniqueCount - 1] = event;
                    continue;
                }
                performance.events[uniqueCount++] = event;
            }
            performance.count = uniqueCount;
            for (std::size_t index = 0; index < performance.count; ++index) {
                auto& event = performance.events[index];
                const double nextTime = index + 1 < performance.count
                    ? performance.events[index + 1].timeSeconds
                    : performance.sectionSeconds;
                event.durationSeconds = std::max(0.001,
                    std::min(event.durationSeconds, nextTime - event.timeSeconds));
            }
        } else if (buildBassScore(bassRecipe_, score) != BassError::none
                   || interpretBassScore(score, interpretation, performance)
                       != BassError::none) {
            return;
        }
        if (bassPitchInverted_) {
            BassPerformance inverted;
            if (!invertBassPerformancePitchContour(performance, 42, inverted))
                return;
            performance = inverted;
        }
        if (bassCycleRecombined_ && hasCurrentSeed_ && seedBassPerformanceValid_) {
            BassPerformance recombined;
            const auto donorOffset = 1u + static_cast<std::size_t>(currentSeed_
                % static_cast<std::uint32_t>(kFormalCycleCount - 1));
            if (!recombineBassPerformanceBars(performance, donorOffset, recombined))
                return;
            performance = recombined;
        }
        if (bassTemporalRetrograde_) {
            BassPerformance reversed;
            if (!retrogradeBassPerformance(performance, reversed))
                return;
            performance = reversed;
        }
        const bool voiceDerivedSeed = (hasCurrentSeed_ || hasMidiSource_)
            && seedBassPerformanceValid_
            && std::any_of(performance.events.begin(),
                performance.events.begin()
                    + static_cast<std::ptrdiff_t>(performance.count),
                [](const BassPlayedEvent& event) {
                    return event.formCycle < kFormalCycleCount;
                });
        if (!voiceDerivedSeed)
            applyBassVoiceRelationship(performance);
        const auto groove = static_cast<GrooveMode>(juce::jlimit(
            0, 3, grooveBox_.getSelectedId() - 1));
        for (std::size_t event = 0; event < performance.count; ++event) {
            const auto formCycle = performance.events[event].formCycle;
            const double localProgress = performance.events[event].timeSeconds
                / performance.sectionSeconds;
            const double progress = formCycle < kFormalCycleCount
                ? (static_cast<double>(formCycle) + localProgress)
                    / static_cast<double>(kFormalCycleCount)
                : localProgress;
            if (!voiceDerivedSeed) {
                performance.events[event].velocity *= grooveAccentAtProgress(
                    localProgress, groove, signature.numerator, signature.denominator);
                performance.events[event].velocity *= expressionAtProgress(progress,
                    static_cast<DynamicCurve>(juce::jlimit(
                        0, 3, dynamicsBox_.getSelectedId() - 1)),
                    static_cast<MusicalIntention>(juce::jlimit(
                        0, 3, intentionBox_.getSelectedId() - 1)));
            } else {
                performance.events[event].velocity *= grooveAccentAtProgress(
                    localProgress, groove, signature.numerator, signature.denominator);
                performance.events[event].velocity *= expressionAtProgress(progress,
                    static_cast<DynamicCurve>(juce::jlimit(
                        0, 3, dynamicsBox_.getSelectedId() - 1)),
                    static_cast<MusicalIntention>(juce::jlimit(
                        0, 3, intentionBox_.getSelectedId() - 1)));
            }
        }
        if (bassLogisticDynamics_ && performance.count > 0) {
            std::uint32_t logisticSeed = bassRecipe_.seed ^ 0x4C4F4749u;
            LogisticMapParameters logistic;
            logistic.initialState = 0.11
                + 0.78 * compositionSeedRandom(logisticSeed);
            if (!applyLogisticBassDynamics(performance, logistic))
                return;
        }
        sanitizeBassPerformance(performance);   // nunca ser recusada por uma nota
        bassDraftPerformance_ = performance;
        bassScoreStrip_.setPerformance(performance, signature.numerator,
            signature.denominator, bassKeyTonic_ >= 0
                ? keyFifthsForMode(bassKeyTonic_, bassKeyScale_) : 0);
        bassPerformancePublishPending_ = true;
        tryPublishBassPerformance();
    }

    void applyBassVoiceRelationship(BassPerformance& performance) {
        if (bassRhythmRelation_ == BassRhythmRelation::independent
            || bassRhythmRelation_ == BassRhythmRelation::convolution
            || bassRhythmRelation_ >= BassRhythmRelation::ecologicalSupport
            || !plansValid_)
            return;
        refreshDisplayPlan();
        if (displayPlanDirty_ || displayPlan_.events.empty()
            || performance.sectionSeconds <= 0.0
            || displayRecipe_.sectionSeconds <= 0.0)
            return;
        const auto voiceCount = static_cast<std::uint8_t>(juce::jlimit(2,
            static_cast<int>(kMaxActiveVoices),
            activeVoiceCount_.load(std::memory_order_relaxed)));
        const auto signature = timeSignatureForChoice(meterBox_.getSelectedId());
        const double section = performance.sectionSeconds;
        const double step = 15.0 / juce::jmax(1.0, bassRecipe_.bpm);
        std::array<std::vector<double>, kFormalCycleCount> voiceTimesByCycle;
        const auto recipeIndex = static_cast<std::size_t>(juce::jlimit(
            0, static_cast<int>(kRecipeVariantCount - 1),
            selectedRecipe_.load(std::memory_order_relaxed)));
        const double formalPhaseAmount = phaseIndex(recipeIndex) * kPhaseStepCycles;
        const double quarterNotesPerSection = 4.0 * signature.numerator * 4.0
            / static_cast<double>(signature.denominator);
        const double swingRatio = juce::jlimit(0.5, 0.67,
            swingSlider_.getValue() / 100.0);
        for (std::size_t cycle = 0; cycle < kFormalCycleCount; ++cycle) {
            auto cycleRecipe = displayRecipe_;
            cycleRecipe.voiceCount = voiceCount;
            const auto [phaseOffset, phaseSlope] =
                formalPhaseArcForDrawing(cycle, formalPhaseAmount);
            for (std::size_t voice = 1; voice < cycleRecipe.voiceCount; ++voice) {
                cycleRecipe.voices[voice].cyclesPerSection += phaseSlope;
                cycleRecipe.voices[voice].phaseCycles += phaseOffset;
            }
            EventPlan cyclePlan;
            if (buildEventPlan(cycleRecipe, cyclePlan) != PlanError::none)
                continue;
            auto& voiceTimes = voiceTimesByCycle[cycle];
            voiceTimes.reserve(cyclePlan.events.size());
            for (const auto& voiceEvent : cyclePlan.events) {
                if (voiceEvent.soundLayer > 0 || voiceEvent.voice >= voiceCount)
                    continue;
                const double progress = std::clamp(voiceEvent.timeSeconds
                    / juce::jmax(cycleRecipe.sectionSeconds, 1.0e-9), 0.0, 1.0);
                const double beatPosition = progress * quarterNotesPerSection;
                const double beatFraction = beatPosition - std::floor(beatPosition);
                const double swung = (std::floor(beatPosition)
                    + (beatFraction < 0.5
                        ? beatFraction * 2.0 * swingRatio
                        : swingRatio + (beatFraction - 0.5)
                            * 2.0 * (1.0 - swingRatio))) / quarterNotesPerSection;
                voiceTimes.push_back(swung * section);
            }
            std::sort(voiceTimes.begin(), voiceTimes.end());
        }
        if (std::all_of(voiceTimesByCycle.begin(), voiceTimesByCycle.end(),
                [](const auto& times) { return times.empty(); }))
            return;
        for (std::size_t index = 0; index < performance.count; ++index) {
            auto& bassEvent = performance.events[index];
            const auto cycle = bassEvent.formCycle < kFormalCycleCount
                ? static_cast<std::size_t>(bassEvent.formCycle) : std::size_t{2};
            const auto& voiceTimes = voiceTimesByCycle[cycle];
            if (voiceTimes.empty())
                continue;
            const double bassTime = std::fmod(bassEvent.timeSeconds, section);
            double nearestDelta = 0.0;
            double nearestDistance = std::numeric_limits<double>::infinity();
            const auto consider = [&](const double voiceTime) {
                const double delta = std::remainder(voiceTime - bassTime, section);
                if (std::abs(delta) < nearestDistance) {
                    nearestDistance = std::abs(delta);
                    nearestDelta = delta;
                }
            };
            const auto next = std::lower_bound(voiceTimes.begin(), voiceTimes.end(), bassTime);
            if (next != voiceTimes.end()) consider(*next);
            if (next != voiceTimes.begin()) consider(*(next - 1));
            if (next == voiceTimes.begin()) consider(voiceTimes.back());
            if (next == voiceTimes.end()) consider(voiceTimes.front());
            if (nearestDistance > step * 1.5)
                continue;
            const double adjustment = bassRhythmRelation_ == BassRhythmRelation::follow
                ? nearestDelta
                : std::clamp(std::remainder(nearestDelta + step * 0.5, section),
                             -step, step);
            double moved = std::fmod(bassTime + adjustment, section);
            if (moved < 0.0)
                moved += section;
            bassEvent.timeSeconds = moved;
        }
        std::sort(performance.events.begin(),
                  performance.events.begin() + static_cast<std::ptrdiff_t>(performance.count),
                  [](const BassPlayedEvent& left, const BassPlayedEvent& right) {
                      if (left.timeSeconds < right.timeSeconds) return true;
                      if (right.timeSeconds < left.timeSeconds) return false;
                      return left.formCycle < right.formCycle;
                  });
        std::size_t uniqueCount = 0;
        for (std::size_t index = 0; index < performance.count; ++index) {
            const auto event = performance.events[index];
            if (uniqueCount > 0
                && bassEventsCollideWithinSameCycle(
                    performance.events[uniqueCount - 1], event, step * 0.25)) {
                if (event.velocity > performance.events[uniqueCount - 1].velocity)
                    performance.events[uniqueCount - 1] = event;
                continue;
            }
            performance.events[uniqueCount++] = event;
        }
        performance.count = uniqueCount;
        for (std::size_t index = 0; index < performance.count; ++index) {
            auto& event = performance.events[index];
            double next = section;
            for (std::size_t candidate = index + 1;
                 candidate < performance.count; ++candidate) {
                if (performance.events[candidate].formCycle == event.formCycle) {
                    next = performance.events[candidate].timeSeconds;
                    break;
                }
            }
            event.durationSeconds = std::min(event.durationSeconds,
                std::max(0.001, next - event.timeSeconds));
        }
    }

    void tryPublishBassPerformance() {
        if (!bassPerformancePublishPending_)
            return;
        int available = 0;
        if (!bassPerformanceSlotState_.compare_exchange_strong(
                available, 1, std::memory_order_acquire, std::memory_order_relaxed))
            return;
        bassPerformanceSlot_ = bassDraftPerformance_;
        bassPublishedPerformance_ = bassDraftPerformance_;
        bassPerformanceSlotState_.store(2, std::memory_order_release);
        bassPerformancePublishPending_ = false;
    }

    int topControlsY() const noexcept {
        return 24;
    }

    int pinnedHeaderHeight() const noexcept {
        return 72;
    }

    juce::Rectangle<int> infoPanelMovementBounds() const noexcept {
        const int visibleTop = pageViewport_ != nullptr
            ? pageViewport_->getViewPositionY() : 0;
        const int visibleHeight = pageViewport_ != nullptr
            ? pageViewport_->getHeight() : getHeight();
        constexpr int horizontalMargin = 24;
        constexpr int verticalMargin = 14;
        const int top = visibleTop + pinnedHeaderHeight() + verticalMargin;
        const int bottom = visibleTop + visibleHeight
            - kPinnedFooterHeight - verticalMargin;
        return {horizontalMargin, top,
                juce::jmax(0, getWidth() - 2 * horizontalMargin),
                juce::jmax(0, bottom - top)};
    }

    juce::Rectangle<int> infoPanelBounds() const noexcept {
        const auto available = infoPanelMovementBounds();
        const bool simpleTextPanel = !infoPanelIsLearn_ && !infoPanelIsMixer_
            && !infoPanelIsBass_ && !infoPanelIsGeometry_;
        const int preferredWidth = simpleTextPanel ? 760
            : infoPanelIsLearn_ ? 980 : 1140;
        const int preferredHeight = simpleTextPanel ? 360
            : infoPanelIsLearn_ ? 620 : 752;
        const int width = juce::jmin(preferredWidth, available.getWidth());
        const int height = juce::jmin(preferredHeight, available.getHeight());
        const int maximumX = juce::jmax(available.getX(),
            available.getRight() - width);
        const int maximumY = juce::jmax(available.getY(),
            available.getBottom() - height);
        if (infoPanelPositionValid_)
            return {juce::jlimit(available.getX(), maximumX,
                                 infoPanelPosition_.x),
                    juce::jlimit(available.getY(), maximumY,
                                 infoPanelPosition_.y),
                    width, height};
        return {available.getX() + (available.getWidth() - width) / 2,
                available.getY() + (available.getHeight() - height) / 2,
                width, height};
    }

