    void updateGeometryCurve() {
        const int selected = juce::jlimit(1, 17, geometryShapeBox_.getSelectedId());
        const auto curve = static_cast<GeometryCurve>(selected - 1);
        const int terms = static_cast<int>(geometryFourierSlider_.getValue());
        const int billiardPattern = juce::jlimit(0, 6,
            geometryBilliardPatternBox_.getSelectedId() - 1);
        const GeometryLissajousParameters lissajous{
            geometryLissajousXFrequencyBox_.getSelectedId(),
            geometryLissajousYFrequencyBox_.getSelectedId(),
            geometryLissajousPhaseSlider_.getValue(),
            geometryLissajousXAmplitudeSlider_.getValue(),
            geometryLissajousYAmplitudeSlider_.getValue()};
        geometryTraceView_.setCurve(curve, terms, billiardPattern, lissajous);
        const bool spiral = curve == GeometryCurve::spiral;
        geometrySourceVoiceOneButton_.setButtonText(utf8("V1 ← y(t)"));
        geometrySourceVoiceOneButton_.setTooltip(localized(language_,
            spiral ? "Ativo: y(t) conduz os acentos da V1; os ataques permanecem regulares."
                   : "Ativo: y(t) influencia ataques e acentos da V1.",
            spiral ? "On: y(t) shapes V1 accents; attacks remain regular."
                   : "On: y(t) influences V1 attacks and accents.",
            spiral ? "Actif : y(t) façonne les accents de V1 ; attaques régulières."
                   : "Actif : y(t) influence les attaques et accents de V1."));
        Point2D warmup;
        (void) geometryCurvePoint(curve, 0.0, 1.0, 0.0, terms, warmup,
                                  billiardPattern, lissajous);
        const bool enabled = geometrySourceVoiceOneButton_.getToggleState();
        geometrySourceVoiceOne_.store(enabled, std::memory_order_release);
        geometrySourceVoiceOneCurve_.store(selected - 1, std::memory_order_relaxed);
        geometrySourceVoiceOneTerms_.store(terms, std::memory_order_relaxed);
        renderer_.setGeometryVoiceOneSource(enabled, curve, terms, billiardPattern,
                                            lissajous);
        repaint(patternFieldPreviewBounds(performancePanels(),
            performancePanels().field.getWidth() - 20).toNearestInt());
    }

    void updateGeometryPanelMode() {
        const bool showCurves = true;
        const bool pendulumStudy = geometryPendulumStudyButton_.getToggleState();
        const bool rhythmicStudy = geometryOrbitButton_.getToggleState()
            || geometryStudyButton_.getToggleState();
        const bool midiStudy = showCurves && !pendulumStudy
            && geometryStudyButton_.getToggleState()
            && !geometryOrbitButton_.getToggleState();
        geometryOrbitButton_.setVisible(showCurves && !pendulumStudy);
        geometryStudyButton_.setVisible(showCurves && !pendulumStudy);
        midiImportButton_.setVisible(midiStudy);
        midiImportBarsBox_.setVisible(midiStudy);
        midiImportSummaryLabel_.setVisible(midiStudy);
        // Keep the function/curve selector present in Study and Orbit so the
        // visible calculation remains discoverable while inspecting cycles.
        geometryShapeBox_.setVisible(showCurves && !pendulumStudy);
        const int shapeId = geometryShapeBox_.getSelectedId();
        const bool showBilliard = showCurves && !pendulumStudy && !rhythmicStudy && shapeId == 12;
        const bool showFourier = showCurves && !pendulumStudy && !rhythmicStudy
            && (shapeId == 6 || shapeId == 7);
        const bool showLissajous = showCurves && !pendulumStudy && !rhythmicStudy && shapeId == 5;
        for (auto& label : geometryLissajousLabels_)
            label.setVisible(showLissajous);
        geometryLissajousXFrequencyBox_.setVisible(showLissajous);
        geometryLissajousYFrequencyBox_.setVisible(showLissajous);
        geometryLissajousPhaseSlider_.setVisible(showLissajous);
        geometryLissajousXAmplitudeSlider_.setVisible(showLissajous);
        geometryLissajousYAmplitudeSlider_.setVisible(showLissajous);
        geometryFourierLabel_.setVisible(showFourier);
        geometryFourierSlider_.setVisible(showFourier);
        geometryBilliardPatternBox_.setVisible(showBilliard);
        geometrySourceVoiceOneButton_.setVisible(showCurves && !pendulumStudy && !rhythmicStudy);
        geometryPendulumStudyButton_.setVisible(showCurves);
        geometryTraceView_.setVisible(showCurves);
        updateStudyHistoryButtons();
        updateGeometryCurve();
        resized();
    }

