    void setLearnTopic(const int topic) {
        if (topic != 8 && learnRhythmPracticeMode_)
            endLearnRhythmPractice();
        else if (topic != 8)
            stopLearnRhythmPreview();
        infoPanelIsLearn_ = true;
        currentLearnTopic_ = juce::jlimit(1, 9, topic);
        setInfoContent(learnTopicContent(language_, currentLearnTopic_));
        for (std::size_t i = 0; i < learnTabButtons_.size(); ++i)
            learnTabButtons_[i].setToggleState(
                static_cast<int>(i + 1) == currentLearnTopic_, juce::dontSendNotification);
        updateLearnRhythmExplorer();
        resized();
        repaint();
    }

    void updateLearnRhythmExplorer() {
        if (updatingLearnRhythmExplorer_)
            return;
        updatingLearnRhythmExplorer_ = true;
        const bool visible = infoPanelIsLearn_ && currentLearnTopic_ == 8;
        const int divisions = juce::jlimit(3, 16,
            learnRhythmDivisionBox_.getSelectedId() > 0
                ? learnRhythmDivisionBox_.getSelectedId() : 4);
        const std::uint32_t patternCount = std::uint32_t{1} << divisions;
        learnRhythmPatternSlider_.setRange(1.0,
            static_cast<double>(patternCount), 1.0);
        const auto patternNumber = static_cast<std::uint32_t>(juce::jlimit(
            1, static_cast<int>(patternCount),
            static_cast<int>(std::lround(learnRhythmPatternSlider_.getValue()))));
        learnRhythmPatternSlider_.setValue(patternNumber,
                                           juce::dontSendNotification);
        const auto mask = learnRhythmPracticeMode_
            ? learnRhythmPracticeResponse_ : patternNumber - 1u;
        if (learnRhythmPracticeMode_) {
            juce::String status;
            if (learnRhythmPracticeResult_ == 3) {
                status = localized(language_,
                    "Percurso concluído. Bom trabalho de escuta!",
                    "Path complete. Excellent listening!",
                    "Parcours terminé. Belle écoute !");
            } else if (learnRhythmProgressiveMode_
                       && learnRhythmPracticeResult_ == 1) {
                status = localized(language_,
                    "Etapa concluída. Avance para continuar.",
                    "Stage complete. Advance to continue.",
                    "Étape terminée. Avancez pour continuer.");
            } else if (learnRhythmPracticeResult_ == 1) {
                status = localized(language_, "Correto. Bom ouvido!",
                    "Correct. Good ear!", "Correct. Bonne écoute !");
            } else if (learnRhythmPracticeResult_ == 2) {
                status = localized(language_, "Ainda não. Ouça e tente outra vez.",
                    "Not yet. Listen and try again.",
                    "Pas encore. Écoutez et réessayez.");
            } else if (learnRhythmProgressiveMode_) {
                status = localized(language_, "Percurso · etapa ", "Path · stage ",
                    "Parcours · étape ") + juce::String(learnRhythmPathStage_ + 1)
                    + localized(language_, " DE 5", " OF 5", " SUR 5")
                    + localized(language_, " · pressione Ouvir, depois marque as posições.",
                        " · press Play, then mark the positions.",
                        " · appuyez sur Écouter, puis marquez les positions.");
            } else {
                status = localized(language_,
                    "Pressione Ouvir, depois marque as posições do padrão.",
                    "Press Play, then mark the pattern positions.",
                    "Appuyez sur Écouter, puis marquez les positions du motif.");
            }
            learnRhythmSummaryLabel_.setText(status, juce::dontSendNotification);
        } else {
            learnRhythmSummaryLabel_.setText(
                localized(language_, "PADRÃO ", "PATTERN ", "MOTIF ")
                    + juce::String(patternNumber)
                    + localized(language_, " DE ", " OF ", " SUR ")
                    + juce::String(patternCount)
                    + (learnRhythmBarMode_
                        ? localized(language_, " · COMPASSO 4/4", " · 4/4 BAR",
                                    " · MESURE 4/4")
                        : learnRhythmTripletBarMode_
                            ? localized(language_, " · COMPASSO 3/4 · TERCINAS",
                                " · 3/4 BAR · TRIPLETS",
                                " · MESURE 3/4 · TRIOLETS")
                            : juce::String{})
                    + "   2^"
                    + juce::String(divisions), juce::dontSendNotification);
        }
        learnRhythmDivisionLabel_.setVisible(visible);
        learnRhythmDivisionBox_.setVisible(visible);
        learnRhythmDivisionBox_.setEnabled(visible && !learnRhythmPracticeMode_);
        learnRhythmPatternSlider_.setVisible(visible && !learnRhythmPracticeMode_);
        learnRhythmSummaryLabel_.setVisible(visible);
        learnRhythmPreviousButton_.setVisible(visible && !learnRhythmPracticeMode_);
        learnRhythmNextButton_.setVisible(visible && !learnRhythmPracticeMode_);
        learnRhythmRandomButton_.setVisible(visible && !learnRhythmPracticeMode_);
        learnRhythmBarButton_.setVisible(visible && !learnRhythmPracticeMode_);
        learnRhythmPreviewButton_.setVisible(visible);
        learnRhythmPracticeButton_.setVisible(visible);
        learnRhythmPathButton_.setVisible(visible && !learnRhythmPracticeMode_);
        learnRhythmPathButton_.setButtonText(localized(language_, "Percurso",
            "Path", "Parcours"));
        learnRhythmBarButton_.setButtonText(learnRhythmBarMode_
            ? localized(language_, "Sortear 3/4", "Roll 3/4", "Tirer 3/4")
            : localized(language_, "Sortear compasso 4/4", "Roll a 4/4 bar",
                        "Tirer une mesure 4/4"));
        learnRhythmPracticeButton_.setButtonText(learnRhythmPracticeMode_
            ? localized(language_, "Encerrar", "Exit", "Terminer")
            : localized(language_, "Praticar", "Practice", "Pratiquer"));
        learnRhythmCheckButton_.setVisible(visible && learnRhythmPracticeMode_);
        learnRhythmCheckButton_.setButtonText(
            learnRhythmPracticeResult_ == 3
                ? localized(language_, "Concluído", "Complete", "Terminé")
                : learnRhythmProgressiveMode_
                    && learnRhythmPracticeResult_ == 1
                        ? localized(language_, "Avançar", "Next", "Suivant")
                        : localized(language_, "Conferir", "Check", "Vérifier"));
        learnRhythmCheckButton_.setEnabled(learnRhythmPracticeResult_ != 3);
        for (std::size_t cell = 0; cell < learnRhythmCellButtons_.size(); ++cell) {
            auto& button = learnRhythmCellButtons_[cell];
            const bool inRange = cell < static_cast<std::size_t>(divisions);
            button.setVisible(visible && inRange);
            if (!inRange)
                continue;
            const bool active = (mask & (std::uint32_t{1} << cell)) != 0;
            button.setToggleState(active, juce::dontSendNotification);
            button.setButtonText(utf8(active ? "●" : "·"));
            button.setTooltip(localized(language_, "Posição ", "Position ", "Position ")
                + juce::String(static_cast<int>(cell + 1)) + utf8(" · ")
                + localized(language_, active ? "ataque" : "pausa",
                    active ? "hit" : "rest", active ? "attaque" : "silence"));
        }
        if (visible && infoPanelVisible_)
            resized();
        updatingLearnRhythmExplorer_ = false;
    }

    void updateLearnRhythmPreviewButton() {
        const bool running = learnRhythmPreviewButton_.getToggleState();
        learnRhythmPreviewButton_.setButtonText(running
            ? localized(language_, "Parar", "Stop", "Arrêter")
            : localized(language_, "Ouvir", "Play", "Écouter"));
        learnRhythmPreviewButton_.setTooltip(localized(language_,
            "Toca o padrão uma vez sem iniciar nem alterar a composição.",
            "Play the pattern once without starting or changing the composition.",
            "Joue le motif une fois sans démarrer ni modifier la composition."));
    }

    void stopLearnRhythmPreview() {
        if (!learnRhythmPreviewButton_.getToggleState()
            && !learnRhythmPreviewStartRequested_.load(std::memory_order_acquire)
            && !learnRhythmPreviewAudioActive_.load(std::memory_order_acquire))
            return;
        learnRhythmPreviewButton_.setToggleState(false, juce::dontSendNotification);
        learnRhythmPreviewStartRequested_.store(false, std::memory_order_relaxed);
        learnRhythmPreviewCancelRequested_.store(true, std::memory_order_release);
        updateLearnRhythmPreviewButton();
    }

    void saveLearnRhythmPracticeSelection() {
        learnRhythmPracticeSavedDivisions_ =
            learnRhythmDivisionBox_.getSelectedId();
        learnRhythmPracticeSavedPattern_ = static_cast<std::uint32_t>(
            std::lround(learnRhythmPatternSlider_.getValue()));
        learnRhythmPracticeSavedBarMode_ = learnRhythmBarMode_;
        learnRhythmPracticeSavedTripletBarMode_ = learnRhythmTripletBarMode_;
    }

    void startLearnRhythmChallenge(const int requestedDivisions) {
        stopLearnRhythmPreview();
        const int divisions = juce::jlimit(3, 16, requestedDivisions);
        learnRhythmDivisionBox_.setSelectedId(divisions,
            juce::dontSendNotification);
        const std::uint32_t count = std::uint32_t{1} << divisions;
        learnRhythmPracticeChallenge_ = 1u
            + static_cast<std::uint32_t>(
                juce::Random::getSystemRandom().nextInt(
                    static_cast<int>(count - 2u)));
        learnRhythmPracticeResponse_ = 0;
        learnRhythmPracticeResult_ = 0;
        learnRhythmPracticeMode_ = true;
        learnRhythmPreviewMask_.store(learnRhythmPracticeChallenge_,
            std::memory_order_relaxed);
        updateLearnRhythmExplorer();
    }

    void advanceLearnRhythmPath() {
        constexpr std::array<int, 5> pathDivisions{4, 6, 8, 12, 16};
        if (learnRhythmPathStage_ + 1 >= static_cast<int>(pathDivisions.size())) {
            learnRhythmPracticeResult_ = 3;
            updateLearnRhythmExplorer();
            return;
        }
        ++learnRhythmPathStage_;
        startLearnRhythmChallenge(
            pathDivisions[static_cast<std::size_t>(learnRhythmPathStage_)]);
    }

    void endLearnRhythmPractice() {
        stopLearnRhythmPreview();
        learnRhythmPracticeMode_ = false;
        learnRhythmPracticeResult_ = 0;
        learnRhythmProgressiveMode_ = false;
        learnRhythmBarMode_ = learnRhythmPracticeSavedBarMode_;
        learnRhythmTripletBarMode_ = learnRhythmPracticeSavedTripletBarMode_;
        learnRhythmDivisionBox_.setSelectedId(
            learnRhythmPracticeSavedDivisions_, juce::dontSendNotification);
        learnRhythmPatternSlider_.setRange(1.0,
            static_cast<double>(std::uint32_t{1}
                << juce::jlimit(3, 16, learnRhythmPracticeSavedDivisions_)), 1.0);
        learnRhythmPatternSlider_.setValue(
            juce::jlimit(1.0,
                static_cast<double>(std::uint32_t{1}
                    << juce::jlimit(3, 16, learnRhythmPracticeSavedDivisions_)),
                static_cast<double>(learnRhythmPracticeSavedPattern_)),
            juce::dontSendNotification);
        updateLearnRhythmExplorer();
    }

    void refreshInfoPanelLanguage() {
        if (!infoPanelVisible_)
            return;
        if (infoPanelIsLearn_)
            setLearnTopic(currentLearnTopic_);
        else if (infoPanelIsMixer_)
            setInfoContent({localized(language_, "Mixer · 8 stems", "Mixer · 8 stems",
                                      "Mixeur · 8 stems"), {}});
        else if (infoPanelIsBass_)
            setInfoContent({localized(language_, "Baixo · oscilador e envelopes",
                                      "Bass · oscillator and envelopes",
                                      "Basse · oscillateur et enveloppes"), {}});
        else if (infoPanelIsGeometry_) {
            updateGeometryPanelMode();
        }
        else
            setInfoContent(aboutContent(language_));
    }

