    void clearSeedAfterManualEdit() {
        if (!hasCurrentSeed_)
            return;
        variationBaseNeedsRefresh_ = true;
    }

    void updateVoiceRhythmControlMode() {
        const auto recipeIndex = static_cast<std::size_t>(juce::jlimit(
            0, static_cast<int>(kRecipeVariantCount - 1),
            selectedRecipe_.load(std::memory_order_relaxed)));
        seedEditor_.setTextToShowWhenEmpty(hasCurrentSeed_
            ? localized(language_, "SEED · 8 HEX", "SEED · 8 HEX", "GRAINE · 8 HEX")
            : localized(language_, "VAZIO · MANUAL", "EMPTY · MANUAL", "VIDE · MANUEL"),
            colour(palette::soft));
        seedEditor_.setTooltip(localized(language_,
            hasCurrentSeed_
                ? "Seed determinística de ritmo, família sonora, geometria e expressão. Começa em Campo livre; escolha a máscara no rodapé e edite os timbres no Mixer. Apague o campo e pressione Enter para editar sem seed."
                : "Modo manual ativo. Use Seed aleatória no Mixer ou digite oito algarismos hexadecimais para gerar uma receita.",
            hasCurrentSeed_
                ? "Deterministic seed for rhythm, sound family, geometry and expression. Starts in Open Field; choose a mask in the footer and edit sounds in the Mixer. Clear the field and press Enter to edit without a seed."
                : "Manual mode active. Use Random seed in the Mixer, or enter eight hexadecimal digits to generate a recipe.",
            hasCurrentSeed_
                ? "Graine déterministe pour le rythme, la famille sonore, la géométrie et l'expression. Elle commence en Champ libre ; choisissez le masque dans le pied de page et modifiez les sons dans le mixeur. Effacez le champ puis Entrée pour éditer sans graine."
                : "Mode manuel actif. Utilisez Graine aléatoire dans le mixeur ou saisissez huit chiffres hexadécimaux pour générer une recette."));
        for (std::size_t voice = 0; voice < kMaxActiveVoices; ++voice) {
            auto& slider = voiceCycleSliders_[voice];
            auto& label = voiceCycleLabels_[voice];
            const float stored = voiceCycleOverrides_[voice].load(
                std::memory_order_relaxed);
            const double cycles = stored > 0.0f ? stored
                : recipes_[recipeIndex].voices[voice].cyclesPerSection;
            if (hasCurrentSeed_) {
                label.setText(localized(language_, "CICLOS/SEÇÃO", "CYCLES/SECTION",
                                         "CYCLES/SECTION"), juce::dontSendNotification);
                slider.setRange(0.5, 16.0, 0.25);
                slider.setValue(cycles, juce::dontSendNotification);
                slider.setTooltip(localized(language_,
                    "Ciclos da fórmula nesta seção; cada ciclo produz dois ataques-base.",
                    "Formula cycles in this section; each cycle yields two base hits.",
                    "Cycles de la formule dans cette section ; chaque cycle produit deux attaques de base."));
            } else {
                label.setText(localized(language_, "TOQUES/SEÇÃO", "HITS/SECTION",
                                         "FRAPPES/SECTION"), juce::dontSendNotification);
                slider.setRange(1.0, 32.0, 1.0);
                slider.setValue(juce::jlimit(1.0, 32.0, std::round(cycles * 2.0)),
                                juce::dontSendNotification);
                slider.setTooltip(localized(language_,
                    "Sem seed: escolha 1–32 ataques nesta seção. Os ataques seguem a fase de cada stem; mudanças atualizam no próximo bloco de áudio.",
                    "Without a seed: choose 1–32 hits in this section. Hits follow each stem’s phase; changes update in the next audio block.",
                    "Sans graine : choisissez 1–32 frappes dans cette section. Elles suivent la phase du stem ; le changement s'actualise au prochain bloc audio."));
                voiceCycleOverrides_[voice].store(static_cast<float>(cycles),
                                                   std::memory_order_relaxed);
            }
        }
        percussionKeyButton_.setButtonText(localized(language_, "PERC. NO TOM",
            "DRUMS IN KEY", "PERC. DANS LE TON"));
        manualCompositionButton_.setButtonText(hasCurrentSeed_
            ? localized(language_, "MODO MANUAL", "MANUAL MODE", "MODE MANUEL")
            : localized(language_, "SEED ALEATÓRIA", "RANDOM SEED",
                        "GRAINE ALÉATOIRE"));
        manualCompositionButton_.setToggleState(!hasCurrentSeed_,
                                                 juce::dontSendNotification);
        manualCompositionButton_.setTooltip(hasCurrentSeed_
            ? localized(language_,
                "Alterna para composição sem seed; os sliders do Mixer passam a mostrar toques por stem.",
                "Switch to seedless composition; Mixer sliders then show hits per stem.",
                "Passe à la composition sans graine ; les curseurs du mixeur indiquent alors les frappes par stem.")
            : localized(language_,
                "Gera uma seed nova e retorna aos ciclos determinados pela receita.",
                "Generate a new seed and return to recipe-defined cycles.",
                "Génère une nouvelle graine et revient aux cycles définis par la recette."));
    }

    void clearSeedForManualComposition() {
        formalCycleCellsEnabled_.fill(false);
        rhythmicCellsDirty_ = true;
        if (!manualBassScore_)
            bassRecipe_ = makeDefaultBassRecipe();
        hasCurrentSeed_ = false;
        currentSeed_ = 0;
        audioDevelopmentSeed_.store(0, std::memory_order_relaxed);
        audioDevelopmentEnabled_.store(false, std::memory_order_relaxed);
        seedBassPerformanceValid_ = false;
        manualBassScore_ = true;
        variationBaseNeedsRefresh_ = true;
        seedEditor_.setText({}, juce::dontSendNotification);
        seedEditor_.setColour(juce::TextEditor::outlineColourId, colour(palette::line));
        updateVoiceRhythmControlMode();
        displayPlanDirty_ = true;
        requestBassPerformanceRebuild();
        updateBassEditorControls();
        updateStatusLabel();
        repaint();
    }

    void markManualBassEdit() {
        if (hasCurrentSeed_) {
            manualBassScore_ = true;
            seedBassPerformanceValid_ = false;
        }
        bassCycleRecombined_ = false;
        bassCycleRecombinationButton_.setToggleState(false,
                                                      juce::dontSendNotification);
        updateBassCycleRecombinationLabel();
        variationBaseNeedsRefresh_ = true;
    }

