        bassPhraseEnabled_ = scene.bassPhrase;
        percussionKeyEnabled_.store(scene.percussionKey, std::memory_order_relaxed);
        percussionKeyButton_.setToggleState(scene.percussionKey, juce::dontSendNotification);
        rhythmicCellsDirty_ = true;
        bassPhraseButton_.setToggleState(bassPhraseEnabled_, juce::dontSendNotification);
        bassCycleRecombinationButton_.setToggleState(bassCycleRecombined_,
                                                      juce::dontSendNotification);
        bassLogisticDynamics_ = scene.bassLogisticDynamics;
        bassLogisticButton_.setToggleState(bassLogisticDynamics_,
            juce::dontSendNotification);
        updateBassLogisticDynamicsLabel();
        updateBassCycleRecombinationLabel();
