    void applySoundFamily(const int family, const bool clearSeed = true) {
        using S = SoundCharacter;
        const auto value = [](const S sound) { return static_cast<int>(sound); };
        soundFamilyIndex_.store(juce::jlimit(-1, 16, family),
                                std::memory_order_relaxed);
        if (hasMidiSource_) {
            // MIDI lanes have semantic kit roles. A family changes their
            // timbre profile but never remaps kick to a hat or conga.
            if (clearSeed)
                clearSeedAfterManualEdit();
            updateFormulaPreview(selectedMixerVoice_);
            updateChannelLevels();
            repaint(0, mixerSectionY(), getWidth(), mixerSectionHeight());
            return;
        }
        if (family == -1) {
            for (std::size_t voice = 0; voice < kMaxActiveVoices; ++voice) {
                voiceSoundOverrides_[voice].store(-1, std::memory_order_relaxed);
                voiceSoundBoxes_[voice].setSelectedId(1,
                    juce::dontSendNotification);
            }
            if (clearSeed)
                clearSeedAfterManualEdit();
            updateFormulaPreview(selectedMixerVoice_);
            updateChannelLevels();
            repaint(0, mixerSectionY(), getWidth(), mixerSectionHeight());
            return;
        }
        if (family < 0 || family >= 17)
            return;
        const auto sounds = soundFamilyVoiceSounds(family);
        for (std::size_t voice = 0; voice < kMaxActiveVoices; ++voice) {
            const auto sound = value(sounds[voice]);
            voiceSoundOverrides_[voice].store(sound,
                                               std::memory_order_relaxed);
            voiceSoundBoxes_[voice].setSelectedId(sound + 2,
                                                   juce::dontSendNotification);
        }
        if (clearSeed)
            clearSeedAfterManualEdit();
        updateFormulaPreview(selectedMixerVoice_);
        updateChannelLevels();
        repaint(0, mixerSectionY(), getWidth(), mixerSectionHeight());
    }

