    void updateFormulaPreview(const std::size_t voice) {
        if (voice >= kMaxVoices || voice != selectedMixerVoice_)
            return;
        const int transform = juce::jlimit(0, 9,
            voiceTransforms_[voice].load(std::memory_order_relaxed));
        const std::array<juce::String, 10> formulas = {
            "sin(theta)", "-sin(theta)", "2*abs(sin(theta))-1",
            "(sin(theta)+0.5*sin(2*theta))/1.5",
            "sin(theta)*(0.65+0.35*cos(theta/2))",
            "round(4*sin(theta))/4", "sin(theta)^3", "sin(3*theta)",
            "(2/pi)*asin(sin(theta))", "tanh(2*sin(theta))/tanh(2)"};
        const float coupling = voiceCouplings_[voice].load(std::memory_order_relaxed);
        const float phaseOffset = formulaPhaseOffsets_[voice].load(
            std::memory_order_relaxed);
        auto expression = formulas[static_cast<std::size_t>(transform)];
        if (voice > 0 && coupling > 0.0f)
            expression = "(1-lambda)*" + expression + "+lambda*V"
                + juce::String(static_cast<int>(voice)) + "  lambda="
                + juce::String(coupling, 2);
        const auto shiftedTheta = "(theta+2pi*" + juce::String(phaseOffset, 3) + ")";
        expression = expression.replace("theta", shiftedTheta);
        formulaPreviewLabel_.setText("V" + juce::String(static_cast<int>(voice + 1))
                                         + " = " + expression,
                                     juce::dontSendNotification);
    }

    void updateChannelLevels() {
        if (bassMixerControlsReady_) {
            bassMixerMuteButton_.setToggleState(bassMuteButton_.getToggleState(),
                                                juce::dontSendNotification);
            bassMixerSoloButton_.setToggleState(bassSoloButton_.getToggleState(),
                                                juce::dontSendNotification);
            updateBassEnableButtonLabel();
        }
        const auto active = static_cast<std::size_t>(juce::jlimit(
            2, static_cast<int>(kMaxActiveVoices),
            activeVoiceCount_.load(std::memory_order_relaxed)));
        std::array<float, kMaxVoices> requestedLevels{};
        std::array<bool, kMaxVoices> muted{};
        std::array<bool, kMaxVoices> solo{};
        for (std::size_t voice = 0; voice < kMaxVoices; ++voice) {
            requestedLevels[voice] = static_cast<float>(
                channelSliders_[voice].getValue());
            muted[voice] = muteButtons_[voice].getToggleState();
            solo[voice] = soloButtons_[voice].getToggleState();
        }
        const bool bassSolo = bassSoloButton_.getToggleState();
        const auto effective = resolveMixerLevels(requestedLevels, muted, solo,
            active, 1.0f,
            bassEnabled_.load(std::memory_order_acquire),
            bassMuteButton_.getToggleState(), bassSolo);
        const std::array<juce::String, kMidiDrumLaneCount> midiLaneNames = {
            localized(language_, "BUMBO", "KICK", "GC"),
            localized(language_, "CAIXA", "SNARE", "CAISSE"),
            localized(language_, "CH. FECH.", "HH CLOSED", "HH FERMÉ"),
            localized(language_, "CH. ABER.", "HH OPEN", "HH OUVERT"),
            localized(language_, "TOMS", "TOMS", "TOMS"),
            localized(language_, "PRATOS", "CYMBALS", "CYMBALES"),
            localized(language_, "PERC. MÃO", "HAND PERC.", "PERC. MAIN"),
            localized(language_, "OUTROS", "OTHER", "AUTRE")};
        const std::array<juce::String, kMidiDrumLaneCount> midiLaneFunctions = {
            localized(language_, "Pulso grave e ancoragem do compasso",
                "Low pulse and bar anchor", "Pulsation grave et ancrage de la mesure"),
            localized(language_, "Contratempo e resposta",
                "Backbeat and response", "Contretemps et réponse"),
            localized(language_, "Subdivisão e marcação regular",
                "Subdivision and steady timekeeping", "Subdivision et maintien régulier du temps"),
            localized(language_, "Abertura e sustentação de transições",
                "Open sustain and transitions", "Ouverture et soutien des transitions"),
            localized(language_, "Movimento e viradas",
                "Movement and fills", "Mouvement et breaks"),
            localized(language_, "Acentos e marcadores de seção",
                "Accents and section markers", "Accents et repères de section"),
            localized(language_, "Contrapadrão rítmico",
                "Rhythmic counter-pattern", "Contre-motif rythmique"),
            localized(language_, "Peça auxiliar; função definida pelo músico",
                "Auxiliary part; role set by the musician",
                "Partie auxiliaire ; rôle défini par le musicien")};
        for (std::size_t voice = 0; voice < kMaxVoices; ++voice) {
            const bool withinInstrumentLimit = voice < kMaxActiveVoices;
            channelLabels_[voice].setVisible(false);
            mixerVoiceSelectButtons_[voice].setVisible(withinInstrumentLimit);
            channelSliders_[voice].setVisible(withinInstrumentLimit);
            channelPanLabels_[voice].setVisible(withinInstrumentLimit);
            channelPanSliders_[voice].setVisible(withinInstrumentLimit);
            channelPanMotionLabels_[voice].setVisible(withinInstrumentLimit);
            channelPanMotionSliders_[voice].setVisible(withinInstrumentLimit);
            channelPanTrajectoryEditors_[voice].setVisible(withinInstrumentLimit);
            channelVariationLabels_[voice].setVisible(withinInstrumentLimit);
            channelVariationSliders_[voice].setVisible(withinInstrumentLimit);
            voiceTransformBoxes_[voice].setVisible(withinInstrumentLimit);
            voiceSoundBoxes_[voice].setVisible(withinInstrumentLimit);
            voiceCouplingSliders_[voice].setVisible(withinInstrumentLimit);
            formulaPhaseLabels_[voice].setVisible(withinInstrumentLimit);
            formulaPhaseOffsetSliders_[voice].setVisible(withinInstrumentLimit);
            voiceCycleLabels_[voice].setVisible(withinInstrumentLimit);
            voiceCycleSliders_[voice].setVisible(withinInstrumentLimit);
            voiceRhythmPhaseLabels_[voice].setVisible(withinInstrumentLimit);
            voiceRhythmPhaseSliders_[voice].setVisible(withinInstrumentLimit);
            voiceEventRuleBoxes_[voice].setVisible(withinInstrumentLimit);
            muteButtons_[voice].setVisible(withinInstrumentLimit);
            soloButtons_[voice].setVisible(withinInstrumentLimit);
            ornamentButtons_[voice].setVisible(withinInstrumentLimit);
            const bool enabled = voice < active;
            const bool mutedVoice = muteButtons_[voice].getToggleState();
            const float stemAlpha = enabled ? (mutedVoice ? 0.72f : 1.0f) : 0.30f;
            const auto stemTint = voiceTint(voice);
            auto& select = mixerVoiceSelectButtons_[voice];
            const juce::String stemName = "V"
                + juce::String(static_cast<int>(voice + 1));
            if (hasMidiSource_ && voice < kMidiDrumLaneCount) {
                const auto& laneName = midiLaneNames[voice];
                select.setButtonText((voice == selectedMixerVoice_ ? utf8("▶ ") : "")
                    + stemName + utf8(" · ") + laneName);
                const auto rolePrefix = language_ == UiLanguage::english
                    ? utf8("MIDI source role: ")
                    : language_ == UiLanguage::french
                        ? utf8("Rôle MIDI source : ")
                        : utf8("Papel de origem MIDI: ");
                const auto roleSuffix = language_ == UiLanguage::english
                    ? utf8(". Select to edit this stem's sound, formula and controls.")
                    : language_ == UiLanguage::french
                        ? utf8(". Sélectionnez pour modifier le timbre, la formule et les réglages de ce stem.")
                        : utf8(". Selecione para editar o timbre, a fórmula e os controles deste stem.");
                const auto functionPrefix = language_ == UiLanguage::english
                    ? utf8("Musical function: ")
                    : language_ == UiLanguage::french
                        ? utf8("Fonction musicale : ")
                        : utf8("Função musical: ");
                select.setTooltip(rolePrefix + laneName + utf8(" · ")
                    + functionPrefix + midiLaneFunctions[voice] + roleSuffix);
            } else {
                const int sound = voiceSoundOverrides_[voice].load(
                    std::memory_order_relaxed);
                juce::String soundName;
                if (sound == static_cast<int>(SoundCharacter::hihat))
                    soundName = localized(language_, "Ch. fechado", "Closed hat", "Charl. fermé");
                else if (sound == static_cast<int>(SoundCharacter::openHihat))
                    soundName = localized(language_, "Ch. aberto", "Open hat", "Charl. ouv.");
                else if (sound == static_cast<int>(SoundCharacter::rimClick))
                    soundName = localized(language_, "Aro", "Rim click", "Cercle");
                else if (sound >= 0)
                    soundName = voiceSoundBoxes_[voice].getText().upToFirstOccurrenceOf(
                        utf8(" · "), false, false);
                else
                    soundName = soundCharacterBox_.getText().upToFirstOccurrenceOf(
                        utf8(" · "), false, false);
                select.setButtonText((voice == selectedMixerVoice_ ? utf8("▶ ") : "")
                    + stemName + " " + soundName);
                select.setTooltip(localized(language_,
                    "Selecionar este stem para editar fórmula, timbre, ciclos, fase e variação.",
                    "Select this stem to edit formula, sound, cycles, phase and variation.",
                    "Sélectionner ce stem pour éditer formule, timbre, cycles, phase et variation.")
                    + " " + soundName);
            }
            select.setColour(juce::TextButton::buttonColourId,
                stemTint.withAlpha(voice == selectedMixerVoice_
                    ? 0.32f : (enabled ? 0.12f : 0.04f)));
            select.setColour(juce::TextButton::textColourOffId,
                enabled ? stemTint : colour(palette::soft));
            select.setAlpha(enabled ? 1.0f : 0.65f);
            channelLabels_[voice].setText(
                "V" + juce::String(static_cast<int>(voice + 1)) + " "
                    + (enabled
                           ? (mutedVoice
                                  ? localized(language_, "MUTE", "MUTED", "MUET")
                                  : localized(language_, "ATIVO", "ON", "ACTIF"))
                           : localized(language_, "INATIVO", "OFF", "INACTIF")),
                juce::dontSendNotification);
            channelLabels_[voice].setColour(
                juce::Label::textColourId,
                enabled ? stemTint : colour(palette::soft).withAlpha(0.72f));
            channelLabels_[voice].setColour(
                juce::Label::backgroundColourId,
                stemTint.withAlpha(enabled ? (mutedVoice ? 0.07f : 0.16f) : 0.035f));
            channelLabels_[voice].setFont(monoFont(
                9.0f, enabled && !mutedVoice ? juce::Font::bold : juce::Font::plain));
            channelLabels_[voice].setAlpha(enabled ? 1.0f : 0.68f);
            channelSliders_[voice].setAlpha(stemAlpha);
            channelPanLabels_[voice].setAlpha(stemAlpha);
            channelPanSliders_[voice].setAlpha(stemAlpha);
            channelPanMotionLabels_[voice].setAlpha(stemAlpha);
            channelPanMotionSliders_[voice].setAlpha(stemAlpha);
            channelPanTrajectoryEditors_[voice].setAlpha(stemAlpha);
            channelVariationLabels_[voice].setAlpha(stemAlpha);
            channelVariationSliders_[voice].setAlpha(stemAlpha);
            voiceTransformBoxes_[voice].setAlpha(stemAlpha);
            voiceSoundBoxes_[voice].setAlpha(stemAlpha);
            voiceCouplingSliders_[voice].setAlpha(stemAlpha);
            formulaPhaseLabels_[voice].setAlpha(stemAlpha);
            formulaPhaseOffsetSliders_[voice].setAlpha(stemAlpha);
            voiceCycleLabels_[voice].setAlpha(stemAlpha);
            voiceCycleSliders_[voice].setAlpha(stemAlpha);
            voiceRhythmPhaseLabels_[voice].setAlpha(stemAlpha);
            voiceRhythmPhaseSliders_[voice].setAlpha(stemAlpha);
            voiceEventRuleBoxes_[voice].setAlpha(stemAlpha);
            muteButtons_[voice].setAlpha(stemAlpha);
            soloButtons_[voice].setAlpha(stemAlpha);
            ornamentButtons_[voice].setAlpha(stemAlpha);
            channelSliders_[voice].setEnabled(enabled);
            channelPanSliders_[voice].setEnabled(enabled);
            channelPanMotionSliders_[voice].setEnabled(enabled);
            channelVariationSliders_[voice].setEnabled(enabled);
            voiceTransformBoxes_[voice].setEnabled(enabled);
            voiceCouplingSliders_[voice].setEnabled(enabled && voice > 0);
            muteButtons_[voice].setEnabled(enabled);
            soloButtons_[voice].setEnabled(enabled);
            ornamentButtons_[voice].setEnabled(enabled);
            effectiveLevels_[voice].store(effective.voices[voice],
                                          std::memory_order_relaxed);
        }
        bassAudible_.store(effective.bass > 0.0f, std::memory_order_release);
        updateFormulaPreview(selectedMixerVoice_);
        updateChip8Inspector();
    }

