        const int selected = juce::jlimit(1, 4, grooveBox_.getSelectedId());
        grooveBox_.clear(juce::dontSendNotification);
        grooveBox_.addItem(localized(language_, "Reto", "Straight", "Droit"), 1);
        grooveBox_.addItem(localized(language_, "Ternário", "Ternary", "Ternaire"), 2);
        grooveBox_.addItem(localized(language_, "Aditivo", "Additive", "Additif"), 3);
        grooveBox_.addItem(localized(language_, "Contratempo", "Offbeat", "Contretemps"), 4);
