    void refreshExpressionChoices() {
        const int intention = intentionBox_.getNumItems() == 0 ? 3
            : juce::jlimit(1, 4, intentionBox_.getSelectedId());
        const int dynamics = dynamicsBox_.getNumItems() == 0 ? 3
            : juce::jlimit(1, 4, dynamicsBox_.getSelectedId());
        intentionBox_.clear(juce::dontSendNotification);
        intentionBox_.addItem(localized(language_, "Construir", "Build", "Construire"), 1);
        intentionBox_.addItem(localized(language_, "Rarear", "Thin", "Alléger"), 2);
        intentionBox_.addItem(localized(language_, "Encontrar", "Meet", "Rencontrer"), 3);
        intentionBox_.addItem(localized(language_, "Contrastar", "Contrast", "Contraster"), 4);
        dynamicsBox_.clear(juce::dontSendNotification);
        dynamicsBox_.addItem(localized(language_, "Estável", "Steady", "Stable"), 1);
        dynamicsBox_.addItem(localized(language_, "Crescendo", "Crescendo", "Crescendo"), 2);
        dynamicsBox_.addItem(localized(language_, "Arco", "Arch", "Arche"), 3);
        dynamicsBox_.addItem(localized(language_, "Ondas", "Waves", "Ondes"), 4);
        intentionBox_.setSelectedId(intention, juce::dontSendNotification);
        dynamicsBox_.setSelectedId(dynamics, juce::dontSendNotification);
    }

    void refreshBassRhythmRelationChoices() {
        const int previousChoice = bassRhythmRelationBox_.getSelectedId();
        const int selectedChoice = previousChoice >= 1 && previousChoice <= 8
            ? previousChoice : static_cast<int>(bassRhythmRelation_) + 1;
        bassRhythmRelationBox_.clear(juce::dontSendNotification);
        constexpr std::array<std::array<const char*, 3>, 8> names = {{
            {{"Independente", "Independent", "Indépendant"}},
            {{"Seguir ataques", "Follow attacks", "Suivre les attaques"}},
            {{"Responder", "Answer", "Répondre"}},
            {{"Convolução cíclica", "Cyclic convolution", "Convolution cyclique"}},
            {{"Ecologia · apoiar", "Ecology · support", "Écologie · soutien"}},
            {{"Ecologia · imitar", "Ecology · imitate", "Écologie · imitation"}},
            {{"Ecologia · afastar", "Ecology · avoid", "Écologie · écart"}},
            {{"Ecologia · competir", "Ecology · compete", "Écologie · compétition"}}
        }};
        for (std::size_t index = 0; index < names.size(); ++index)
            bassRhythmRelationBox_.addItem(localized(language_, names[index][0],
                names[index][1], names[index][2]), static_cast<int>(index + 1));
        bassRhythmRelationBox_.setSelectedId(selectedChoice,
                                              juce::dontSendNotification);
        bassRhythmRelationBox_.setTooltip(localized(language_,
            "O baixo gerado pela seed é recalculado fora do áudio e entra no próximo bloco. Relações ecológicas usam o λ de cada voz.",
            "Seed-generated bass recalculates outside audio and updates in the next block. Ecological relations use each voice’s λ.",
            "La basse générée par seed est recalculée hors audio et mise à jour au prochain bloc. Les relations écologiques utilisent le λ de chaque voix."));
    }

