    void updateMixerBalanceSensor() {
        const bool active = status_ == AppStatus::playing;
        const float voices = formulaBusRms_.load(std::memory_order_relaxed);
        const float bass = bassBusRms_.load(std::memory_order_relaxed);
        float delta = 0.0f;
        const float currentTrim = static_cast<float>(formulaBusGainSlider_.getValue());
        if (!active || !suggestVoiceTrimDeltaDb(voices, bass, currentTrim, delta)) {
            if (mixerAutoBalanceButton_.isEnabled())
                mixerAutoBalanceButton_.setEnabled(false);
            const auto label = localized(language_,
                active ? "AGUARDA SINAL" : "TOQUE PARA MEDIR",
                active ? "WAITING FOR SIGNAL" : "PLAY TO MEASURE",
                active ? "EN ATTENTE DU SIGNAL" : "JOUER POUR MESURER");
            if (mixerAutoBalanceButton_.getButtonText() != label)
                mixerAutoBalanceButton_.setButtonText(label);
            const auto tooltip = localized(language_,
                "O sensor mede RMS separado das vozes e do baixo durante a reprodução.",
                "The sensor measures separate voice and bass RMS during playback.",
                "Le capteur mesure séparément le RMS des voix et de la basse pendant la lecture.");
            if (mixerAutoBalanceButton_.getTooltip() != tooltip)
                mixerAutoBalanceButton_.setTooltip(tooltip);
            return;
        }
        const double voiceDb = 20.0 * std::log10(static_cast<double>(voices));
        const double bassDb = 20.0 * std::log10(static_cast<double>(bass));
        juce::String adjustment = delta >= 0.0 ? juce::String("+") : juce::String();
        adjustment += juce::String(delta, 1) + " dB";
        const auto prefix = localized(language_, "AJ", "APPLY", "RÉGLER");
        const auto label = prefix + " " + adjustment + utf8(" · V")
            + juce::String(voiceDb, 0) + " B" + juce::String(bassDb, 0);
        if (mixerAutoBalanceButton_.getButtonText() != label)
            mixerAutoBalanceButton_.setButtonText(label);
        const auto tooltip =
            utf8("RMS voix ") + juce::String(voiceDb, 1)
            + utf8(" dBFS · RMS baixo ")
            + juce::String(bassDb, 1) + " dBFS. "
            + localized(language_,
                "Clique para aplicar uma compensação estática ao trim das vozes.",
                "Click to apply static compensation to the voice bus trim.",
                "Cliquer pour appliquer une compensation statique au bus des voix.");
        if (mixerAutoBalanceButton_.getTooltip() != tooltip)
            mixerAutoBalanceButton_.setTooltip(tooltip);
        if (!mixerAutoBalanceButton_.isEnabled())
            mixerAutoBalanceButton_.setEnabled(true);
    }

    void updateStatusLabel() {
        juce::String status;
        if (recordingFinalizing_.load(std::memory_order_acquire)) {
            status = localized(language_, "Finalizando WAV…", "Finalizing WAV…",
                               "Finalisation du WAV…");
        } else if (recordingActive_.load(std::memory_order_acquire)) {
            status = localized(language_, "Gravando master…", "Recording master…",
                               "Enregistrement du master…");
        } else switch (status_) {
            case AppStatus::preparing:
                status = localized(language_, "Preparando áudio…", "Preparing audio…",
                                   "Préparation audio…");
                break;
            case AppStatus::ready:
                status = localized(language_, "Pronto para ouvir", "Ready to play",
                                   "Prêt à écouter");
                break;
            case AppStatus::playing:
                if (sampleRate_.load(std::memory_order_relaxed) > 0.0
                    && renderer_.activeSectionSamples() != sectionSamplesForBpm(
                        bpmSlider_.getValue(),
                        timeSignatureForChoice(meterBox_.getSelectedId()).numerator,
                        timeSignatureForChoice(meterBox_.getSelectedId()).denominator,
                        sampleRate_.load(std::memory_order_relaxed))) {
                    status = localized(language_, "Próxima seção", "Next section",
                                       "Prochaine section");
                } else {
                    const auto cycle = static_cast<std::size_t>(
                        (renderer_.completedBars() / 4u) % kFormalCycleCount);
                    const auto group = cycle < 2
                        ? localized(language_, "CONSTRUÇÃO", "BUILD", "CONSTRUCTION")
                        : cycle < 4
                            ? localized(language_, "MUDANÇA", "SHIFT", "CHANGEMENT")
                            : cycle == 4
                                ? localized(language_, "EXPANSÃO", "EXPANSION", "EXPANSION")
                                : localized(language_, "RETORNO", "RETURN", "RETOUR");
                    status = localized(language_, "FORMA · CICLO ", "FORM · CYCLE ",
                                       "FORME · CYCLE ")
                        + juce::String(static_cast<int>(cycle + 1)) + utf8("/7 · ") + group;
                    if (hasCurrentSeed_ && !finiteFormPlayback_.load(
                            std::memory_order_relaxed)) {
                        const auto passage = renderer_.completedBars()
                            / (4u * kFormalCycleCount);
                        const auto passageRole = passageRoleFor(currentSeed_, passage);
                        juce::String roleLabel = "A";
                        switch (passageRole) {
                            case PassageRole::A: roleLabel = "A"; break;
                            case PassageRole::B: roleLabel = "B"; break;
                            case PassageRole::APrime: roleLabel = "A'"; break;
                            case PassageRole::C: roleLabel = "C"; break;
                            case PassageRole::BPrime: roleLabel = "B'"; break;
                            case PassageRole::Expansion:
                                roleLabel = localized(language_, "EXPANSÃO", "EXPANSION",
                                                      "EXPANSION");
                                break;
                            case PassageRole::CPrime: roleLabel = "C'"; break;
                            case PassageRole::ReturnA:
                                roleLabel = localized(language_, "RETORNO A", "RETURN A",
                                                     "RETOUR A");
                                break;
                        }
                        status += utf8(" · P")
                            + juce::String(static_cast<int>(
                                passage % kPassageRoleCount + 1u))
                            + "/" + juce::String(static_cast<int>(kPassageRoleCount))
                            + utf8(" · ") + roleLabel;
                    }
                }
                break;
            case AppStatus::countIn:
                status = localized(language_, "CONTAGEM · 1 COMPASSO",
                                   "COUNT-IN · 1 BAR", "DÉCOMPTE · 1 MESURE");
                break;
            case AppStatus::paused:
                status = localized(language_, "Pausado · fase preservada",
                                   "Paused · phase preserved",
                                   "Pause · phase conservée");
                break;
            case AppStatus::unavailable:
                status = localized(language_, "Áudio indisponível",
                                   "Audio unavailable", "Audio indisponible");
                break;
        }
        if (status != statusLabel_.getText())
            statusLabel_.setText(status, juce::dontSendNotification);
    }

    void updateFormPlaybackButton() {
        const bool finite = finiteFormPlayback_.load(std::memory_order_acquire);
        formPlaybackButton_.setToggleState(finite, juce::dontSendNotification);
        formPlaybackButton_.setButtonText(finite ? utf8("7×") : utf8("∞"));
        formPlaybackButton_.setTooltip(localized(language_,
            finite
                ? "Forma finita: toca os sete ciclos uma vez e para. Clique para repetir continuamente."
                : "Forma contínua: repete sem parar. Clique para tocar os sete ciclos uma vez.",
            finite
                ? "Finite form: plays the seven cycles once, then stops. Click to loop continuously."
                : "Continuous form: loops without stopping. Click to play the seven cycles once.",
            finite
                ? "Forme finie : joue les sept cycles une fois, puis s’arrête. Cliquez pour boucler."
                : "Forme continue : répète sans arrêt. Cliquez pour jouer les sept cycles une fois."));
    }

    void togglePlayback() {
        if (!audioReady_.load(std::memory_order_acquire)) {
            status_ = AppStatus::unavailable;
            updateStatusLabel();
            return;
        }
        if (metronomeCountInActive_.exchange(false, std::memory_order_acq_rel)) {
            metronomeCountInCancelRequested_.store(true, std::memory_order_release);
            status_ = AppStatus::paused;
            playButton_.setButtonText(localized(language_, "Tocar", "Play", "Jouer"));
            updateStatusLabel();
            repaintPerformancePage();
            return;
        }
        const bool next = !playing_.load(std::memory_order_relaxed);
        if (next && metronomeEnabled_.load(std::memory_order_relaxed))
            metronomeRestartRequested_.store(true, std::memory_order_release);
        const bool startingNewPass = next && status_ != AppStatus::paused;
        const bool countInRequested = next && startingNewPass
            && metronomeEnabled_.load(std::memory_order_relaxed)
            && metronomeCountInEnabled_.load(std::memory_order_relaxed);
        if (startingNewPass) {
            formulaBusRms_.store(0.0f, std::memory_order_relaxed);
            bassBusRms_.store(0.0f, std::memory_order_relaxed);
        }
        if (startingNewPass && finiteFormPlayback_.load(std::memory_order_acquire)) {
            formRestartPending_.store(true, std::memory_order_release);
            finiteFormCompleted_ = false;
            finiteFormStartBars_.store(0, std::memory_order_release);
        } else if (next && finiteFormCompleted_) {
            formRestartPending_.store(true, std::memory_order_release);
            finiteFormCompleted_ = false;
        }
        if (countInRequested) {
            metronomeCountInActive_.store(true, std::memory_order_release);
            metronomeCountInStartRequested_.store(true, std::memory_order_release);
            status_ = AppStatus::countIn;
            playButton_.setButtonText(localized(language_, "Cancelar", "Cancel",
                                                "Annuler"));
            updateStatusLabel();
            repaintPerformancePage();
            return;
        }
        playing_.store(next, std::memory_order_release);
        status_ = next ? AppStatus::playing : AppStatus::paused;
        playButton_.setButtonText(localized(language_, next ? "Parar" : "Tocar",
                                            next ? "Stop" : "Play",
                                            next ? "Arrêter" : "Jouer"));
        updateStatusLabel();
        repaintPerformancePage();
        repaint(0, mixerSectionY(), getWidth(), mixerSectionHeight());
    }

    void timerCallback() override {
        if (maestrucLink_ != nullptr) {
            // o mixer mudou à mão (ou por cena): o Maestruc fica sabendo
            std::vector<double> now;
            now.push_back(static_cast<double>(activeVoiceCount_.load(std::memory_order_relaxed)));
            for (std::size_t voice = 0; voice < kMaxVoices; ++voice) {
                now.push_back(channelSliders_[voice].getValue());
                now.push_back(muteButtons_[voice].getToggleState() ? 1.0 : 0.0);
                now.push_back(soloButtons_[voice].getToggleState() ? 1.0 : 0.0);
            }
            now.push_back(bassMixerLevelSlider_.getValue());
            now.push_back(bassMixerMuteButton_.getToggleState() ? 1.0 : 0.0);
            now.push_back(bassMixerSoloButton_.getToggleState() ? 1.0 : 0.0);
            if (now != maestrucMixerSeen_) {
                maestrucMixerSeen_ = std::move(now);
                maestrucLink_->mixerChanged();
            }
        }
        {   // contexto da pauta de bateria do Study: compasso e sons efetivos
            const auto signature = timeSignatureForChoice(meterBox_.getSelectedId());
            const int globalSound = juce::jlimit(0, 17, soundCharacter_.load(std::memory_order_relaxed));
            std::array<SoundCharacter, kMaxVoices> sounds{};
            for (std::size_t voice = 0; voice < kMaxVoices; ++voice) {
                const int overrideSound = voiceSoundOverrides_[voice].load(std::memory_order_relaxed);
                sounds[voice] = static_cast<SoundCharacter>(overrideSound < 0 ? globalSound : overrideSound);
            }
            geometryTraceView_.setStaffContext(signature.numerator, signature.denominator, sounds);
        }
        if (metronomeCountInCancelled_.exchange(false, std::memory_order_acq_rel)
            && status_ == AppStatus::countIn
            && !metronomeCountInActive_.load(std::memory_order_acquire)) {
            status_ = AppStatus::paused;
            playButton_.setButtonText(localized(language_, "Tocar", "Play", "Jouer"));
            updateStatusLabel();
        }
        if (metronomeCountInFinished_.exchange(false, std::memory_order_acq_rel)
            && playing_.load(std::memory_order_acquire)
            && status_ == AppStatus::countIn) {
            status_ = AppStatus::playing;
            playButton_.setButtonText(localized(language_, "Parar", "Stop",
                                                "Arrêter"));
            updateStatusLabel();
        }
        if (learnRhythmPreviewButton_.getToggleState()
            && learnRhythmPreviewStarted_.load(std::memory_order_acquire)
            && !learnRhythmPreviewAudioActive_.load(std::memory_order_acquire)
            && !learnRhythmPreviewStartRequested_.load(std::memory_order_acquire)) {
            learnRhythmPreviewButton_.setToggleState(false,
                juce::dontSendNotification);
            updateLearnRhythmPreviewButton();
        }
        // Moving an attack changes the bass source. Coalesce expensive score
        // rebuilds during a drag, then do the final rebuild on mouse-up.
        if (bassFollowRhythmPending_ && ++bassFollowRhythmTicks_ >= 6) {
            bassFollowRhythmPending_ = false;
            bassFollowRhythmTicks_ = 0;
            requestBassPerformanceRebuild();
        }
        if (++uiMaintenanceTick_ >= 3) {
            uiMaintenanceTick_ = 0;
            tryPublishBassPerformance();
            tryPublishRhythmicCells();
            captureRecordingConfigurationRevision();
            updateMixerBalanceSensor();
            const auto toDb = [](const float value) {
                return value > 1.0e-8f ? 20.0f * std::log10(value) : -120.0f;
            };
            const float prePeak = preGuardPeak_.load(std::memory_order_relaxed);
            const float postPeak = postMasterPeak_.load(std::memory_order_relaxed);
            const float curveReduction = limiterReduction_.load(std::memory_order_relaxed);
            const float tpIn = preMasterTruePeak_.load(std::memory_order_relaxed);
            const float tpOut = postMasterTruePeak_.load(std::memory_order_relaxed);
            const auto meterText = "MAX PK " + juce::String(toDb(prePeak), 1) + "/"
                + juce::String(toDb(postPeak), 1) + "  TP " + juce::String(toDb(tpIn), 1)
                + "/" + juce::String(toDb(tpOut), 1) + "  LIM "
                + juce::String(curveReduction, 1) + " dB";
            if (meterText != masterMeterLabel_.getText())
                masterMeterLabel_.setText(meterText, juce::dontSendNotification);
            const auto cpuPercent = static_cast<double>(
                cpuLoadMilliPercent_.load(std::memory_order_relaxed)) / 1000.0;
            const auto cpuText = "CPU AUDIO " + juce::String(cpuPercent, 1) + "%";
            if (cpuText != cpuMeterLabel_.getText())
                cpuMeterLabel_.setText(cpuText, juce::dontSendNotification);
            if (recordingActive_.load(std::memory_order_acquire)) {
                const double rate = sampleRate_.load(std::memory_order_relaxed);
                const auto frames = recordingFrames_.load(std::memory_order_relaxed);
                const int limitMinutes = recordingLimitMinutes_.load(
                    std::memory_order_relaxed);
                const auto elapsed = rate > 0.0
                    ? static_cast<std::uint64_t>(static_cast<double>(frames) / rate)
                    : 0u;
                const auto elapsedSeconds = juce::jmin<std::uint64_t>(elapsed,
                    static_cast<std::uint64_t>(limitMinutes) * 60u);
                if (elapsedSeconds != recordingUiElapsedSeconds_) {
                    recordingUiElapsedSeconds_ = elapsedSeconds;
                    const auto clock = juce::String::formatted("%02d:%02d",
                        static_cast<int>(elapsedSeconds / 60u),
                        static_cast<int>(elapsedSeconds % 60u));
                    recordButton_.setButtonText("STOP " + clock);
                }
            }
            if (recordingLimitReached_.load(std::memory_order_acquire))
                finishRecording(true);
            if (status_ == AppStatus::playing
                && finiteFormPlayback_.load(std::memory_order_acquire)
                && renderer_.completedBars() >= finiteFormStartBars_.load(
                    std::memory_order_acquire) + 4u * kFormalCycleCount) {
                playing_.store(false, std::memory_order_release);
                finiteFormCompleted_ = true;
                status_ = AppStatus::ready;
                playButton_.setButtonText(localized(language_, "Tocar", "Play", "Jouer"));
                if (recordingActive_.load(std::memory_order_acquire))
                    finishRecording(false);
                updateStatusLabel();
                repaint(0, mixerSectionY(), getWidth(), mixerSectionHeight());
            }
            if (status_ == AppStatus::preparing
                && audioReady_.load(std::memory_order_acquire)) {
                status_ = AppStatus::ready;
                updateStatusLabel();
            } else if (status_ == AppStatus::preparing && ++audioWaitTicks_ > 90) {
                status_ = AppStatus::unavailable;
                updateStatusLabel();
            } else if (status_ == AppStatus::unavailable
                       && audioReady_.load(std::memory_order_acquire)) {
                status_ = AppStatus::ready;
                updateStatusLabel();
            }
        }
        const auto now = juce::Time::getMillisecondCounter();
        if (!recordingCompletionNotice_.isEmpty()
            && static_cast<std::int32_t>(now - recordingNoticeUntilMs_) >= 0)
            recordingCompletionNotice_.clear();
        const bool transportRunning = playing_.load(std::memory_order_acquire);
        if (!recordingCompletionNotice_.isEmpty()) {
            if (statusLabel_.getText() != recordingCompletionNotice_)
                statusLabel_.setText(recordingCompletionNotice_,
                                     juce::dontSendNotification);
        } else if (transportRunning) {
            updateStatusLabel();
        }
        const auto sectionProgress = renderer_.sectionProgress();
        const auto completedBars = renderer_.completedBars();
        for (auto& panPath : channelPanTrajectoryEditors_)
            if (panPath.isVisible()
                && isViewportRectangleVisible(panPath.getBounds()))
                panPath.setPlaybackPosition(sectionProgress, transportRunning);
        if (bassPianoRoll_.isVisible()
            && isViewportRectangleVisible(bassPianoRoll_.getBounds()))
            bassPianoRoll_.setPlaybackPosition(sectionProgress, transportRunning);
        if (bassScoreStrip_.isVisible()
            && isViewportRectangleVisible(bassScoreStrip_.getBounds()))
            bassScoreStrip_.setPlayback(sectionProgress, static_cast<int>(
                (renderer_.completedBars() / 4u) % kFormalCycleCount), transportRunning);
        if (bassLfoView_.isVisible()
            && isViewportRectangleVisible(bassLfoView_.getBounds()))
            bassLfoView_.setState(bassLfoEnabled_.load(std::memory_order_relaxed),
                static_cast<BassLfoShape>(juce::jlimit(0, 2,
                    bassLfoShape_.load(std::memory_order_relaxed))),
                static_cast<unsigned>(bassLfoPeriod_.load(std::memory_order_relaxed)),
                static_cast<unsigned>(bassLfoDepth_.load(std::memory_order_relaxed)),
                static_cast<BassLfoTarget>(juce::jlimit(0, 2,
                    bassLfoTarget_.load(std::memory_order_relaxed))),
                static_cast<double>(completedBars) / 4.0 + sectionProgress,
                bassRecipe_.cells[bassSelectedStep_].midi,
                calculatedBassMidiForStep(bassSelectedStep_),
                bassRecipe_.cells[bassSelectedStep_].kind == BassCellKind::note,
                language_);
        if (bassPathView_.isVisible()
            && isViewportRectangleVisible(bassPathView_.getBounds()))
            updateBassPathView();
        const auto traceVariant = renderer_.activeVariant();
        const bool geometryVisible = geometryTraceView_.isVisible()
            && isViewportRectangleVisible(geometryTraceView_.getBounds());
        if (geometryVisible && geometryTraceView_.getRhythmicStudyModeForDiagnostics() == 2)
            refreshDisplayPlan();
        if (geometryVisible && traceVariant < recipes_.size()) {
            std::array<double, kMaxVoices> rhythmicCycles{};
            std::array<double, kMaxVoices> rhythmicPhases{};
            std::array<double, kMaxVoices> rhythmicAttackPhases{};
            std::array<int, kMaxVoices> rhythmicAttackRules{};
            const auto rhythmicCount = static_cast<std::size_t>(juce::jlimit(2,
                static_cast<int>(kMaxActiveVoices),
                activeVoiceCount_.load(std::memory_order_relaxed)));
            const auto& traceRecipe = recipes_[traceVariant];
            for (std::size_t voice = 0; voice < rhythmicCount; ++voice) {
                rhythmicCycles[voice] = traceRecipe.voices[voice].cyclesPerSection;
                const float override = voiceCycleOverrides_[voice].load(
                    std::memory_order_relaxed);
                if (override > 0.0f)
                    rhythmicCycles[voice] = override;
                rhythmicPhases[voice] = traceRecipe.voices[voice].phaseCycles
                    + formulaPhaseOffsets_[voice].load(std::memory_order_relaxed);
                rhythmicAttackPhases[voice] = traceRecipe.voices[voice].phaseCycles
                    + voiceRhythmPhaseOffsets_[voice].load(
                        std::memory_order_relaxed);
                const int ruleOverride = voiceEventRuleOverrides_[voice].load(
                    std::memory_order_relaxed);
                rhythmicAttackRules[voice] = ruleOverride >= 0
                    ? ruleOverride
                    : static_cast<int>(traceRecipe.voices[voice].eventRule);
            }
            geometryTraceView_.setRhythmicCycles(rhythmicCycles,
                rhythmicPhases, rhythmicAttackPhases, rhythmicAttackRules,
                rhythmicCount);
            geometryTraceView_.setRhythmicCells(rhythmicCells_);
            double traceCycles = recipes_[traceVariant].voices[0].cyclesPerSection;
            const float cycleOverride = voiceCycleOverrides_[0].load(
                std::memory_order_relaxed);
            if (cycleOverride > 0.0f)
                traceCycles = cycleOverride;
            double secondaryCycles = recipes_[traceVariant].voices[1].cyclesPerSection;
            const float secondaryOverride = voiceCycleOverrides_[1].load(
                std::memory_order_relaxed);
            if (secondaryOverride > 0.0f)
                secondaryCycles = secondaryOverride;
            geometryTraceView_.setTransport(sectionProgress, transportRunning,
                                             traceCycles);
            geometryTraceView_.setPendulumSeed(hasCurrentSeed_ ? currentSeed_ : 0u);
            geometryTraceView_.setCompositionMotion(traceCycles,
                traceRecipe.voices[0].phaseCycles
                    + formulaPhaseOffsets_[0].load(std::memory_order_relaxed),
                secondaryCycles,
                traceRecipe.voices[1].phaseCycles
                    + formulaPhaseOffsets_[1].load(std::memory_order_relaxed));
            geometryTraceView_.setLanguage(language_);
        }
        const bool performanceVisible = isViewportRectangleVisible(
            {0, 0, getWidth(), kPerformancePageHeight});
        if (performanceVisible) {
            refreshDisplayPlan();
            constrainGraphViewToOneSecond();
        }
        // Only the performance canvas animates, and only while transport
        // moves. Repaint the visible page slice so the playhead keeps moving
        // when the user has scrolled below the first performance panel.
        // Com um menu aberto (ComboBox/PopupMenu é componente modal), a
        // animação cai para 10 Hz: o redesenho de 60 Hz em software ocupava a
        // thread de mensagens, e a janela nova do menu ficava transparente
        // (mostrando a área de trabalho) até ser pintada. Autor, 14/11/2026.
        const bool menuOpen = juce::ModalComponentManager::getInstance()
            ->getNumModalComponents() > 0;
        const bool animateThisFrame = !menuOpen || (++menuOpenFrameCounter_ % 6) == 0;
        if (transportRunning && animateThisFrame) {
            const juce::Rectangle<int> performanceArea(
                0, 0, getWidth(), kPerformancePageHeight);
            const juce::Rectangle<int> mixerArea(
                0, mixerSectionY(), getWidth(), mixerSectionHeight());
            const auto visibleArea = pageViewport_ != nullptr
                ? pageViewport_->getViewArea() : performanceArea;
            const auto performanceAnimation = visibleArea.getIntersection(performanceArea);
            if (!performanceAnimation.isEmpty())
                repaint(performanceAnimation);
            const auto mixerAnimation = visibleArea.getIntersection(mixerArea);
            if (!mixerAnimation.isEmpty())
                repaint(mixerAnimation);
        }
    }

    void drawMixerPhaseDials(juce::Graphics& graphics) {
        const auto area = juce::Rectangle<int>(0, mixerSectionY(), getWidth(),
                                               mixerSectionHeight());
        if (!graphics.getClipBounds().intersects(area))
            return;
        const auto recipeIndex = static_cast<std::size_t>(juce::jlimit(
            0, static_cast<int>(kRecipeVariantCount - 1),
            selectedRecipe_.load(std::memory_order_relaxed)));
        const auto& recipe = recipes_[recipeIndex];
        const auto count = static_cast<std::size_t>(juce::jlimit(2,
            static_cast<int>(kMaxActiveVoices),
            activeVoiceCount_.load(std::memory_order_relaxed)));
        constexpr float panelX = 24.0f;
        constexpr float panelInset = 28.0f;
        const float columnWidth = (static_cast<float>(getWidth()) - 36.0f - 56.0f)
            / static_cast<float>(kMaxActiveVoices);
        const float centreY = static_cast<float>(mixerSectionY() + mixerTopPad())
            + 175.0f + static_cast<float>(kMixerBassStripOffset);
        const double progress = renderer_.sectionProgress();
        const auto formalCycle = static_cast<std::size_t>(
            (renderer_.completedBars() / 4u) % kFormalCycleCount);
        const auto formal = formalPhaseArcForDrawing(formalCycle,
            static_cast<double>(phaseIndex(recipeIndex)) * kPhaseStepCycles);

        for (std::size_t voice = 0; voice < count; ++voice) {
            const float stored = voiceCycleOverrides_[voice].load(
                std::memory_order_relaxed);
            const double cycles = stored > 0.0f ? stored
                : recipe.voices[voice].cyclesPerSection;
            const double phaseOffset = voiceRhythmPhaseOffsets_[voice].load(
                std::memory_order_relaxed);
            const auto centreX = panelX + panelInset
                + columnWidth * (static_cast<float>(voice) + 0.5f);
            const float radius = 16.0f;
            const auto tint = voiceTint(voice);
            graphics.setColour(colour(palette::line));
            graphics.drawEllipse(centreX - radius, centreY - radius,
                                 radius * 2.0f, radius * 2.0f, 1.2f);
            const int hits = juce::jlimit(1, 32,
                static_cast<int>(std::lround(cycles * 2.0)));
            for (int hit = 0; hit < hits; ++hit) {
                const double angle = kTau * (static_cast<double>(hit) / hits
                    + phaseOffset) - 0.5 * kTau;
                const float x = centreX + radius * static_cast<float>(std::cos(angle));
                const float y = centreY + radius * static_cast<float>(std::sin(angle));
                graphics.setColour(tint.withAlpha(0.76f));
                graphics.fillEllipse(x - 2.0f, y - 2.0f, 4.0f, 4.0f);
            }
            double phase = cycles * progress + recipe.voices[voice].phaseCycles
                + phaseOffset + formulaPhaseOffsets_[voice].load(
                    std::memory_order_relaxed);
            if (voice > 0)
                phase += formal.first + formal.second * progress;
            phase -= std::floor(phase);
            const double angle = kTau * phase - 0.5 * kTau;
            const juce::Point<float> tip(
                centreX + radius * static_cast<float>(std::cos(angle)),
                centreY + radius * static_cast<float>(std::sin(angle)));
            graphics.setColour(tint);
            graphics.drawLine(centreX, centreY, tip.x, tip.y, 1.9f);
            graphics.fillEllipse(tip.x - 3.7f, tip.y - 3.7f, 7.4f, 7.4f);
        }
    }

    static void drawFunctionGraph(juce::Graphics& graphics,
                                  const juce::Rectangle<float> bounds,
                                  const CompositionRecipe& recipe,
                                  const EventPlan& plan,
                                  const double sectionSeconds,
                                  const double progress,
                                  const double viewStart,
                                  const double viewSpan,
                                  const float amplitudeScale,
                                  const UiLanguage language,
                                  const double swingRatio,
                                  const GrooveMode groove,
                                  const int meterNumerator,
                                  const int meterDenominator,
                                  const DynamicCurve dynamics,
                                  const MusicalIntention intention,
                                  const IntensityLaw law,
                                  const IntensityLaw lawB,
                                  const float blend,
                                  const float amount,
                                  const int selectedStudyVoice,
                                  const int selectedStudyAttack,
                                  const double selectedStudyPosition,
                                  const std::size_t visibleVoiceCount,
                                  const GraphMotion motion,
                                  const GraphAnalysis analysis,
                                  const std::array<VoiceTransform, kMaxVoices>& transforms,
                                  const std::array<float, kMaxVoices>& couplings,
                                  const std::array<float, kMaxVoices>& phaseOffsets,
                                  const std::size_t formalCycle,
                                  const double formalPhaseAmount,
                                  const bool geometryVoiceOne,
                                  const GeometryCurve geometryCurve,
                                  const int geometryFourierTerms,
                                  const int geometryBilliardPattern,
                                  const bool developmentEnabled,
                                  const std::uint32_t developmentSeed,
                                  const std::uint64_t passage) {
        graphics.setColour(colour(palette::graph));
        graphics.fillRect(bounds);
        juce::Graphics::ScopedSaveState save(graphics);
        graphics.reduceClipRegion(bounds.toNearestInt());
        graphics.setColour(colour(palette::line));
        graphics.drawRect(bounds, 1.0f);
        const float plotLeft = bounds.getX() + 31.0f;
        const float plotWidth = juce::jmax(1.0f, bounds.getWidth() - 37.0f);
        // The graph toolbar occupies the first 24 px of the plotting frame.
        // Put its title beneath that row and start the plotted lanes below the
        // title so controls, title, and signal never share the same pixels.
        const float plotTop = bounds.getY()
            + (analysis == GraphAnalysis::intensity ? 86.0f : 53.0f);
        const float laneHeight = juce::jmax(1.0f,
            (bounds.getBottom() - plotTop) / static_cast<float>(visibleVoiceCount));
        const auto atTime = [&](const double fraction) {
            if (motion == GraphMotion::timeline)
                return viewStart + viewSpan * fraction;
            const double direction = motion == GraphMotion::left ? 1.0 : -1.0;
            const double t = progress + direction * (fraction - 0.5) * viewSpan;
            return t - std::floor(t);
        };
        const auto screenForTime = [&](const double t, const int turn) {
            return motion == GraphMotion::timeline
                ? (t - viewStart) / viewSpan
                : 0.5 + (motion == GraphMotion::left ? 1.0 : -1.0)
                    * (t + static_cast<double>(turn) - progress) / viewSpan;
        };
        const double quarterNotesPerSection = 4.0 * meterNumerator * 4.0
            / static_cast<double>(meterDenominator);
        const int quarterGrid = static_cast<int>(std::lround(
            quarterNotesPerSection * 2.0));
        for (int beat = 0; beat <= quarterGrid; ++beat) {
            const double t = static_cast<double>(beat) / quarterGrid;
            for (int turn = motion == GraphMotion::timeline ? 0 : -1;
                 turn <= (motion == GraphMotion::timeline ? 0 : 1); ++turn) {
                const double fraction = screenForTime(t, turn);
                if (fraction < 0.0 || fraction > 1.0)
                    continue;
                const float x = plotLeft + plotWidth * static_cast<float>(fraction);
                graphics.setColour(colour(palette::line).withAlpha(
                    beat % static_cast<int>(std::lround(
                        quarterGrid / 4.0)) == 0 ? 0.85f : 0.45f));
                graphics.drawVerticalLine(static_cast<int>(x), plotTop,
                                          bounds.getBottom() - 1.0f);
            }
        }

        std::array<juce::Colour, kMaxVoices> tints{};
        for (std::size_t voice = 0; voice < tints.size(); ++voice)
            tints[voice] = voiceTint(voice);
        // Plain locals, not a structured binding: lambdas below capture them,
        // and Clang < 16 rejects capturing structured bindings (C++17).
        const auto phaseArc =
            formalPhaseArcForDrawing(formalCycle, formalPhaseAmount);
        const double phaseArcOffset = phaseArc.first;
        const double phaseArcSlope = phaseArc.second;
        constexpr int curveSamples = 512;

        // The intensity laws are composition material in their own right. This
        // view plots A, B and the actual blended multiplier over the same time
        // window as the voice graph, using the renderer's two phase fields.
        if (analysis == GraphAnalysis::intensity) {
            const double cyclesX = recipe.voices[0].cyclesPerSection;
            const double cyclesY = recipe.voices[1].cyclesPerSection
                + phaseArcSlope;
            const MusicalEvent* selectedIntensityEvent = nullptr;
            float selectedFieldMultiplier = 0.0f;
            double selectedEventPosition = -1.0;
            if (selectedStudyVoice >= 0 && selectedStudyAttack >= 0
                && selectedStudyPosition >= 0.0 && selectedStudyPosition < 1.0
                && sectionSeconds > 0.0) {
                for (const auto& event : plan.events) {
                    const double eventPosition = event.timeSeconds / sectionSeconds;
                    if (event.voice == static_cast<std::uint8_t>(selectedStudyVoice)
                        && std::abs(eventPosition - selectedStudyPosition) <= 1.0e-6) {
                        selectedIntensityEvent = &event;
                        selectedEventPosition = eventPosition;
                        const float mixed = blendedIntensityFormulaValue(law, lawB,
                            blend, event.fieldX, event.fieldY, cyclesX, cyclesY);
                        selectedFieldMultiplier = 1.0f - amount + amount * mixed;
                        break;
                    }
                }
            }
            graphics.setColour(colour(palette::soft));
            graphics.setFont(monoFont(8.5f));
            const int equationX = static_cast<int>(bounds.getX() + 31.0f);
            const int equationWidth = juce::jmax(1,
                static_cast<int>(bounds.getWidth() - 40.0f));
            graphics.drawFittedText("A(x,y) = " + intensityLawEquation(
                    law, cyclesX, cyclesY), equationX,
                static_cast<int>(bounds.getY() + 44.0f), equationWidth, 13,
                juce::Justification::centredLeft, 1, 0.62f);
            graphics.drawFittedText("B(x,y) = " + intensityLawEquation(
                    lawB, cyclesX, cyclesY), equationX,
                static_cast<int>(bounds.getY() + 57.0f), equationWidth, 13,
                juce::Justification::centredLeft, 1, 0.62f);
            juce::String consequence = utf8("x,y→F=(1-b)A+bB→I_field=(1-λ)+λF")
                + juce::String("  b=") + juce::String(blend, 2)
                + utf8(" λ=") + juce::String(amount, 2);
            if (selectedIntensityEvent != nullptr)
                consequence += utf8(" · V") + juce::String(selectedStudyVoice + 1)
                    + "#" + juce::String(selectedStudyAttack + 1)
                    + utf8(" I_field×") + juce::String(selectedFieldMultiplier, 2);
            graphics.drawFittedText(consequence, equationX,
                static_cast<int>(bounds.getY() + 70.0f), equationWidth, 13,
                juce::Justification::centredLeft, 1, 0.62f);
            const float plotBottom = bounds.getBottom() - 14.0f;
            const float plotHeight = juce::jmax(1.0f, plotBottom - plotTop);
            const auto yForIntensity = [&](const float value) {
                return plotBottom - plotHeight * std::clamp(value, 0.0f, 1.0f);
            };
            for (const float level : {0.0f, 0.5f, 1.0f}) {
                const float y = yForIntensity(level);
                graphics.setColour(colour(palette::line).withAlpha(
                    level > 0.49f && level < 0.51f ? 0.9f : 0.55f));
                graphics.drawHorizontalLine(static_cast<int>(y), plotLeft,
                                            plotLeft + plotWidth);
                graphics.setColour(colour(palette::soft));
                graphics.setFont(monoFont(9.0f));
                graphics.drawText(juce::String(level, 1),
                    static_cast<int>(bounds.getX() + 2.0f),
                    static_cast<int>(y - 8.0f), 27, 16,
                    juce::Justification::centredLeft);
            }

            juce::Path lawAPath;
            juce::Path lawBPath;
            juce::Path mixPath;
            for (int i = 0; i <= curveSamples; ++i) {
                const double fraction = static_cast<double>(i) / curveSamples;
                const double t = atTime(fraction);
                const auto fieldAt = [&](const std::size_t voice) {
                    const auto& item = recipe.voices[voice];
                    const double phaseArc = voice == 0 ? 0.0
                        : phaseArcOffset + phaseArcSlope * t;
                    return static_cast<float>(std::sin(kTau * (
                        item.cyclesPerSection * t + item.phaseCycles
                        + phaseOffsets[voice] + phaseArc)));
                };
                const float x = fieldAt(0);
                const float y = fieldAt(1);
                const float a = intensityFormulaValue(law, x, y,
                    recipe.voices[0].cyclesPerSection,
                    recipe.voices[1].cyclesPerSection + phaseArcSlope);
                const float b = intensityFormulaValue(lawB, x, y,
                    recipe.voices[0].cyclesPerSection,
                    recipe.voices[1].cyclesPerSection + phaseArcSlope);
                const float mixed = blendedIntensityFormulaValue(law, lawB,
                    blend, x, y, recipe.voices[0].cyclesPerSection,
                    recipe.voices[1].cyclesPerSection + phaseArcSlope);
                const float finalMultiplier = 1.0f - amount + amount * mixed;
                const float px = plotLeft + plotWidth * static_cast<float>(fraction);
                const auto append = [&](juce::Path& path, const float value) {
                    const float py = yForIntensity(value);
                    if (i == 0)
                        path.startNewSubPath(px, py);
                    else
                        path.lineTo(px, py);
                };
                append(lawAPath, a);
                append(lawBPath, b);
                append(mixPath, finalMultiplier);
            }
            graphics.setColour(colour(palette::voiceOne).withAlpha(0.75f));
            graphics.strokePath(lawAPath, juce::PathStrokeType(1.8f,
                juce::PathStrokeType::curved, juce::PathStrokeType::rounded));
            graphics.setColour(colour(palette::voiceTwo).withAlpha(0.75f));
            graphics.strokePath(lawBPath, juce::PathStrokeType(1.8f,
                juce::PathStrokeType::curved, juce::PathStrokeType::rounded));
            graphics.setColour(colour(palette::ink));
            graphics.strokePath(mixPath, juce::PathStrokeType(3.0f,
                juce::PathStrokeType::curved, juce::PathStrokeType::rounded));
            if (selectedIntensityEvent != nullptr) {
                float fraction = -1.0f;
                const int firstTurn = motion == GraphMotion::timeline ? 0 : -1;
                const int lastTurn = motion == GraphMotion::timeline ? 0 : 1;
                for (int turn = firstTurn; turn <= lastTurn; ++turn) {
                    const double candidate = screenForTime(selectedEventPosition, turn);
                    if (candidate >= 0.0 && candidate <= 1.0) {
                        fraction = static_cast<float>(candidate);
                        break;
                    }
                }
                if (fraction >= 0.0f) {
                    const float markerX = plotLeft + plotWidth * fraction;
                    const float markerY = yForIntensity(selectedFieldMultiplier);
                    const float diameter = 10.0f;
                    graphics.setColour(colour(palette::white));
                    graphics.fillEllipse(markerX - diameter * 0.5f,
                        markerY - diameter * 0.5f, diameter, diameter);
                    graphics.setColour(voiceTint(static_cast<std::size_t>(
                        selectedStudyVoice)));
                    graphics.drawEllipse(markerX - diameter * 0.5f,
                        markerY - diameter * 0.5f, diameter, diameter, 2.0f);
                }
            }
            const float playheadFraction = motion == GraphMotion::timeline
                ? static_cast<float>((progress - viewStart) / viewSpan) : 0.5f;
            if (playheadFraction >= 0.0f && playheadFraction <= 1.0f) {
                const float x = plotLeft + plotWidth * playheadFraction;
                graphics.setColour(colour(palette::soft).withAlpha(0.65f));
                graphics.drawVerticalLine(static_cast<int>(x), plotTop, plotBottom);
                graphics.setColour(colour(palette::white));
                graphics.fillEllipse(x - 4.0f, plotTop - 4.0f, 8.0f, 8.0f);
                graphics.setColour(colour(palette::ink));
                graphics.drawEllipse(x - 4.0f, plotTop - 4.0f, 8.0f, 8.0f, 1.2f);
            }
            graphics.setFont(monoFont(10.0f));
            const int legendY = static_cast<int>(bounds.getY() + 28.0f);
            const auto legend = [&](const int x, const juce::String& label,
                                    const juce::uint32 tint) {
                graphics.setColour(colour(tint));
                graphics.fillEllipse(static_cast<float>(x),
                    static_cast<float>(legendY + 5), 7.0f, 7.0f);
                graphics.setColour(colour(palette::ink));
                graphics.drawText(label, x + 11, legendY, 86, 17,
                                  juce::Justification::centredLeft);
            };
            legend(static_cast<int>(plotLeft), utf8("A · ")
                + intensityLawShortName(law), palette::voiceOne);
            legend(static_cast<int>(plotLeft + 103.0f), utf8("B · ")
                + intensityLawShortName(lawB), palette::voiceTwo);
            legend(static_cast<int>(plotLeft + 206.0f), utf8("MIX  ·  ")
                + juce::String(blend, 2), palette::ink);
            return;
        }
        std::array<std::array<float, curveSamples + 1>, kMaxVoices> sampledValues{};
        int currentCurveSample = -1;
        const auto formulaAt = [&](auto&& self, const std::size_t voiceIndex,
                                   const double t) -> float {
            const auto& voice = recipe.voices[voiceIndex];
            const double phaseArc = voiceIndex == 0 ? 0.0
                : phaseArcOffset + phaseArcSlope * t;
            const double theta = kTau * (voice.cyclesPerSection * t
                + voice.phaseCycles + phaseOffsets[voiceIndex] + phaseArc);
            float value = static_cast<float>(std::sin(theta));
            if (voiceIndex == 0 && geometryVoiceOne) {
                Point2D point;
                if (geometryCurvePoint(geometryCurve, t, voice.cyclesPerSection,
                        voice.phaseCycles + phaseOffsets[voiceIndex] + phaseArc,
                        geometryFourierTerms, point, geometryBilliardPattern))
                    value = static_cast<float>(point.y);
            }
            switch (transforms[voiceIndex]) {
                case VoiceTransform::sine: break;
                case VoiceTransform::invert: value = -value; break;
                case VoiceTransform::rectify: value = 2.0f * std::abs(value) - 1.0f; break;
                case VoiceTransform::harmonic:
                    value = (value + 0.5f * static_cast<float>(std::sin(2.0 * theta))) / 1.5f;
                    break;
                case VoiceTransform::amplitude:
                    value *= 0.65f + 0.35f * static_cast<float>(std::cos(theta * 0.5));
                    break;
                case VoiceTransform::quantized: value = std::round(value * 4.0f) / 4.0f; break;
                case VoiceTransform::cubic: value = value * value * value; break;
                case VoiceTransform::thirdHarmonic:
                    value = static_cast<float>(std::sin(3.0 * theta));
                    break;
                case VoiceTransform::triangle:
                    value = static_cast<float>(0.63661977236758134308
                        * std::asin(std::clamp(value, -1.0f, 1.0f)));
                    break;
                case VoiceTransform::softClip:
                    value = static_cast<float>(std::tanh(2.0 * value) / std::tanh(2.0));
                    break;
            }
            if (voiceIndex > 0 && couplings[voiceIndex] > 0.0f) {
                const float previous = currentCurveSample >= 0
                    ? sampledValues[voiceIndex - 1][static_cast<std::size_t>(
                          currentCurveSample)]
                    : self(self, voiceIndex - 1, t);
                value = (1.0f - couplings[voiceIndex]) * value
                    + couplings[voiceIndex] * previous;
            }
            return value;
        };
        const auto graphVoiceCount = std::min(recipe.voiceCount, visibleVoiceCount);
        for (std::size_t voiceIndex = 0; voiceIndex < graphVoiceCount; ++voiceIndex) {
            for (int i = 0; i <= curveSamples; ++i) {
                currentCurveSample = i;
                sampledValues[voiceIndex][static_cast<std::size_t>(i)] =
                    formulaAt(formulaAt, voiceIndex,
                        static_cast<double>(i) / curveSamples);
            }
        }
        currentCurveSample = -1;
        std::array<std::array<float, curveSamples + 1>, kMaxVoices> analysisValues{};
        std::array<float, kMaxVoices> analysisScales{};
        if (analysis == GraphAnalysis::derivative) {
            for (std::size_t voice = 0; voice < graphVoiceCount; ++voice) {
                float maximum = 0.0f;
                for (int i = 0; i <= curveSamples; ++i) {
                    const int left = juce::jmax(0, i - 1);
                    const int right = juce::jmin(curveSamples, i + 1);
                    const float derivative = (sampledValues[voice][static_cast<std::size_t>(right)]
                        - sampledValues[voice][static_cast<std::size_t>(left)])
                        * static_cast<float>(curveSamples)
                        / static_cast<float>(right - left);
                    analysisValues[voice][static_cast<std::size_t>(i)] = derivative;
                    maximum = juce::jmax(maximum, std::abs(derivative));
                }
                analysisScales[voice] = maximum > 1.0e-7f ? maximum : 1.0f;
            }
        } else if (analysis == GraphAnalysis::integral) {
            for (std::size_t voice = 0; voice < graphVoiceCount; ++voice) {
                float accumulated = 0.0f;
                float maximum = 0.0f;
                analysisValues[voice][0] = 0.0f;
                for (int i = 1; i <= curveSamples; ++i) {
                    accumulated += 0.5f * (
                        sampledValues[voice][static_cast<std::size_t>(i - 1)]
                        + sampledValues[voice][static_cast<std::size_t>(i)])
                        / static_cast<float>(curveSamples);
                    analysisValues[voice][static_cast<std::size_t>(i)] = accumulated;
                    maximum = juce::jmax(maximum, std::abs(accumulated));
                }
                analysisScales[voice] = maximum > 1.0e-7f ? maximum : 1.0f;
            }
        }
        const auto graphValueAt = [&](const std::size_t voice, const double t) {
            const double position = std::clamp(t, 0.0, 1.0) * curveSamples;
            const auto left = static_cast<std::size_t>(position);
            const auto right = std::min(left + 1, static_cast<std::size_t>(curveSamples));
            const float fraction = static_cast<float>(position - static_cast<double>(left));
            const auto& values = analysis == GraphAnalysis::signal
                ? sampledValues[voice] : analysisValues[voice];
            float value = values[left] + fraction * (values[right] - values[left]);
            if (analysis != GraphAnalysis::signal)
                value /= analysisScales[voice];
            return value;
        };
        for (std::size_t voiceIndex = 0; voiceIndex < graphVoiceCount; ++voiceIndex) {
            const float mid = plotTop + laneHeight
                * (static_cast<float>(voiceIndex) + 0.5f);
            graphics.setColour(colour(palette::line));
            graphics.drawHorizontalLine(static_cast<int>(mid), plotLeft,
                                        plotLeft + plotWidth);
            graphics.setColour(tints[voiceIndex]);
            graphics.setFont(monoFont(visibleVoiceCount > 8 ? 9.0f : 10.0f));
            graphics.drawText("V" + juce::String(static_cast<int>(voiceIndex + 1)),
                              static_cast<int>(bounds.getX() + 3.0f),
                              static_cast<int>(mid - 9.0f), 27, 18,
                              juce::Justification::centredLeft);
            juce::Path fullPath;
            juce::Path tracedPath;
            constexpr int samples = curveSamples;
            const int last = motion == GraphMotion::timeline
                ? juce::jlimit(-1, samples, static_cast<int>(std::floor(
                    (progress - viewStart) / viewSpan * samples)))
                : samples;
            double previousTime = -2.0;
            for (int i = 0; i <= samples; ++i) {
                currentCurveSample = i;
                const double t = atTime(static_cast<double>(i) / samples);
                const float x = plotLeft + plotWidth
                    * static_cast<float>(i) / samples;
                const float value = graphValueAt(voiceIndex, t);
                const float viewScale = analysis == GraphAnalysis::signal
                    ? amplitudeScale : 1.0f;
                const float y = mid - value * laneHeight * 0.36f * viewScale;
                const bool wrapped = motion != GraphMotion::timeline
                    && i > 0 && std::abs(t - previousTime) > 0.5;
                if (i == 0 || wrapped)
                    fullPath.startNewSubPath(x, y);
                else
                    fullPath.lineTo(x, y);
                if (i <= last) {
                    if (i == 0 || wrapped)
                        tracedPath.startNewSubPath(x, y);
                    else
                        tracedPath.lineTo(x, y);
                }
                previousTime = t;
            }
            graphics.setColour(tints[voiceIndex].withAlpha(0.27f));
            graphics.strokePath(fullPath, juce::PathStrokeType(1.2f));
            graphics.setColour(tints[voiceIndex]);
            graphics.strokePath(tracedPath, juce::PathStrokeType(2.1f));
        }
        const double sectionIndex = static_cast<double>(passage
            * kFormalCycleCount + formalCycle);
        const auto patternAllows = [&](const double x, const double y,
                                       const double t) {
            return patternFieldAllows(recipe.patternMode, x, y,
                                      sectionIndex + t, developmentSeed);
        };
        const auto drawEventMarker = [&](const std::size_t voice,
                                         const double t,
                                         const double fieldX,
                                         const double fieldY) {
            if (voice >= visibleVoiceCount || t < 0.0 || t >= 1.0)
                return;
            const double beatPosition = t * quarterNotesPerSection;
            const double beatFraction = beatPosition - std::floor(beatPosition);
            const double swungTime = (std::floor(beatPosition)
                + (beatFraction < 0.5
                    ? beatFraction * 2.0 * swingRatio
                    : swingRatio + (beatFraction - 0.5)
                        * 2.0 * (1.0 - swingRatio))) / quarterNotesPerSection;
            const float mid = plotTop + laneHeight
                * (static_cast<float>(voice) + 0.5f);
            const float displayScale = analysis == GraphAnalysis::signal
                ? amplitudeScale : 1.0f;
            const float y = mid - graphValueAt(voice, t)
                * laneHeight * 0.36f * displayScale;
            const double cycleOneSlope = formalCycle == 2 || formalCycle == 3
                ? 0.5 * formalPhaseAmount
                : formalCycle == 5 || formalCycle == 6
                    ? -0.5 * formalPhaseAmount : 0.0;
            const float mapped = juce::jlimit(0.0f, 1.0f,
                blendedIntensityFormulaValue(law, lawB, blend,
                    static_cast<float>(fieldX),
                    static_cast<float>(fieldY),
                    recipe.voices[0].cyclesPerSection,
                    recipe.voices[1].cyclesPerSection + cycleOneSlope));
            const float intensity = 1.0f - juce::jlimit(0.0f, 1.0f, amount)
                + juce::jlimit(0.0f, 1.0f, amount) * mapped;
            const float fieldWeight = patternFieldWeight(recipe.patternMode,
                fieldX, fieldY, sectionIndex + t, developmentSeed);
            const float development = developmentEnabled
                ? passageEventWeight(developmentSeed, passage, voice, t) : 1.0f;
            const float radius = 1.3f + 1.6f * intensity
                * grooveAccentAtProgress(swungTime, groove,
                                         meterNumerator, meterDenominator)
                * expressionAtProgress(t, dynamics, intention) * development
                * fieldWeight;
            for (int turn = motion == GraphMotion::timeline ? 0 : -1;
                 turn <= (motion == GraphMotion::timeline ? 0 : 1); ++turn) {
                const double fraction = screenForTime(swungTime, turn);
                if (fraction < 0.0 || fraction > 1.0)
                    continue;
                const float x = plotLeft + plotWidth * static_cast<float>(fraction);
                graphics.setColour(tints[voice % tints.size()].withAlpha(
                    development <= 0.0f ? 0.45f : 1.0f));
                if (development <= 0.0f) {
                    graphics.drawLine(x - 2.0f, y - 2.0f, x + 2.0f, y + 2.0f, 1.0f);
                    graphics.drawLine(x - 2.0f, y + 2.0f, x + 2.0f, y - 2.0f, 1.0f);
                } else {
                    graphics.fillEllipse(x - radius, y - radius,
                                         radius * 2.0f, radius * 2.0f);
                    if (development >= 1.12f) {
                        graphics.drawEllipse(x - radius - 1.5f, y - radius - 1.5f,
                            radius * 2.0f + 3.0f, radius * 2.0f + 3.0f, 0.9f);
                    } else if (development <= 0.62f) {
                        graphics.drawEllipse(x - radius - 1.0f, y - radius - 1.0f,
                            radius * 2.0f + 2.0f, radius * 2.0f + 2.0f, 0.8f);
                    }
                }
            }
        };
        const auto [axisOneOffset, axisOneSlope] =
            formalPhaseArcForDrawing(formalCycle, formalPhaseAmount);
        const double axisOneCycles = recipe.voices[0].cyclesPerSection;
        const double axisTwoCycles = recipe.voices[1].cyclesPerSection + axisOneSlope;
        const double axisOnePhase = recipe.voices[0].phaseCycles;
        const double axisTwoPhase = recipe.voices[1].phaseCycles + axisOneOffset;
        if (geometryVoiceOne) {
            for (const auto& event : plan.events) {
                if (event.voice != 0)
                    continue;
                drawEventMarker(0, event.timeSeconds / recipe.sectionSeconds,
                                event.fieldX, event.fieldY);
            }
        }
        constexpr double phaseEpsilon = 1.0e-12;
        for (std::size_t voice = 0;
             voice < std::min(recipe.voiceCount, visibleVoiceCount); ++voice) {
            if (geometryVoiceOne && voice == 0)
                continue;
            const double slope = voice == 0 ? 0.0
                : (formalCycle == 2 || formalCycle == 3
                    ? 0.5 * formalPhaseAmount
                    : formalCycle == 5 || formalCycle == 6
                        ? -0.5 * formalPhaseAmount : 0.0);
            const double offset = voice == 0 ? 0.0
                : formalPhaseArcForDrawing(formalCycle, formalPhaseAmount).first;
            const double cycles = recipe.voices[voice].cyclesPerSection + slope;
            double phase = recipe.voices[voice].phaseCycles + offset;
            phase -= std::floor(phase);
            const std::array<double, 2> thresholds =
                recipe.voices[voice].eventRule == EventRule::centreCrossings
                    ? std::array<double, 2>{0.0, 0.5}
                    : std::array<double, 2>{0.25, 0.75};
            for (const double threshold : thresholds) {
                const auto first = static_cast<std::int64_t>(
                    std::ceil(phase - threshold - phaseEpsilon));
                const double end = cycles + phase - threshold;
                for (std::int64_t crossing = first;
                     static_cast<double>(crossing) < end - phaseEpsilon;
                     ++crossing) {
                    const double t = (static_cast<double>(crossing)
                        + threshold - phase) / cycles;
                    if (t < -phaseEpsilon || t >= 1.0 - phaseEpsilon)
                        continue;
                    const double x = std::sin(kTau
                        * (axisOneCycles * t + axisOnePhase));
                    const double y = std::sin(kTau
                        * (axisTwoCycles * t + axisTwoPhase));
                    if (patternAllows(x, y, t))
                        drawEventMarker(voice, std::max(0.0, t), x, y);
                }
            }
        }
        const double cursorFraction = motion == GraphMotion::timeline
            ? (progress - viewStart) / viewSpan : 0.5;
        if (cursorFraction >= 0.0 && cursorFraction <= 1.0) {
            const float x = plotLeft + plotWidth
                * static_cast<float>(cursorFraction);
            graphics.setColour(colour(palette::ink).withAlpha(0.65f));
            graphics.drawVerticalLine(static_cast<int>(x), plotTop,
                                      bounds.getBottom() - 1.0f);
            for (std::size_t voice = 0; voice < graphVoiceCount; ++voice) {
                const float mid = plotTop + laneHeight
                    * (static_cast<float>(voice) + 0.5f);
                const float scale = analysis == GraphAnalysis::signal
                    ? amplitudeScale : 1.0f;
                const float y = mid - graphValueAt(voice, progress)
                    * laneHeight * 0.36f * scale;
                graphics.setColour(tints[voice].withAlpha(0.25f));
                graphics.fillEllipse(x - 5.5f, y - 5.5f, 11.0f, 11.0f);
                graphics.setColour(colour(palette::graph));
                graphics.fillEllipse(x - 3.3f, y - 3.3f, 6.6f, 6.6f);
                graphics.setColour(tints[voice]);
                graphics.fillEllipse(x - 2.0f, y - 2.0f, 4.0f, 4.0f);
            }
        }
        graphics.setColour(colour(palette::ink));
        graphics.setFont(monoFont(10.0f));
        const auto view = motion == GraphMotion::timeline
            ? juce::String(viewStart * sectionSeconds, 2) + utf8("–")
                + juce::String((viewStart + viewSpan) * sectionSeconds, 2) + " s"
            : localized(language, "FLUXO ", "FLOW ", "FLUX ")
                + (motion == GraphMotion::left ? utf8("←") : utf8("→"));
        const auto analysisName = analysis == GraphAnalysis::signal
            ? juce::String("f(t)")
            : analysis == GraphAnalysis::derivative
                ? utf8("f′(τ)") : utf8("∫₀ᵗ f(u)du");
        const auto graphTitle = (analysis == GraphAnalysis::intensity
            ? localized(language, "INTENSIDADE / A → B", "INTENSITY / A → B",
                         "INTENSITÉ / A → B")
            : localized(language, "ONDA / ", "WAVE / ", "ONDE / ")
                + analysisName) + utf8("  ·  ") + view;
        // o título cede à direita o espaço medido do texto da passagem
        // ("P1 BASE M0.17 rot7 dir r3"), para os dois não se sobreporem
        juce::String passageText;
        if (developmentEnabled) {
            const auto state = passageDevelopmentState(developmentSeed, passage);
            passageText = "P" + juce::String(static_cast<juce::int64>(passage + 1u))
                + (passage == 0u ? " BASE" : " DEV")
                + " M" + juce::String(state.memory, 2)
                + " rot" + juce::String(static_cast<int>(state.rotation))
                + (state.inverted ? " inv" : " dir")
                + " r" + juce::String(static_cast<int>(state.restCell + 1u));
        }
        const int passageReserve = passageText.isEmpty() ? 0
            : juce::GlyphArrangement::getStringWidthInt(monoFont(8.2f), passageText) + 14;
        const int graphTitleWidth = juce::jmax(60, juce::jmin(220,
            static_cast<int>(bounds.getWidth()) - 16 - passageReserve));
        graphics.drawFittedText(graphTitle,
            juce::Rectangle<int>(static_cast<int>(bounds.getX()) + 8,
                static_cast<int>(bounds.getY()) + 28, graphTitleWidth, 18),
            juce::Justification::centredLeft, 1, 0.7f);
        if (passageText.isNotEmpty()) {
            graphics.setColour(colour(palette::soft));
            graphics.setFont(monoFont(8.2f));
            graphics.drawText(passageText,
                static_cast<int>(bounds.getRight()) - 192,
                static_cast<int>(bounds.getY()) + 28, 184, 18,
                juce::Justification::centredRight);
        }
    }

    static void drawGeometryCurvePreview(
            juce::Graphics& graphics, const juce::Rectangle<float> bounds,
            const GeometryCurve curve, const double cycles, const int terms,
            const int billiardPattern,
            const GeometryLissajousParameters lissajous,
            const UiLanguage language, const double progress) {
        if (bounds.getWidth() < 80.0f || bounds.getHeight() < 100.0f)
            return;
        graphics.setColour(colour(palette::graph));
        graphics.fillRoundedRectangle(bounds, 6.0f);
        graphics.setColour(colour(palette::line).withAlpha(0.72f));
        graphics.drawRoundedRectangle(bounds.reduced(0.5f), 6.0f, 1.0f);
        graphics.setColour(colour(palette::soft));
        graphics.setFont(monoFont(9.5f));
        graphics.drawFittedText(bounds.getWidth() < 150.0f
            ? localized(language, "CURVA", "CURVE", "COURBE")
            : localized(language,
                "CURVA SELECIONADA", "SELECTED CURVE", "COURBE CHOISIE"),
            bounds.toNearestInt().withHeight(22).reduced(6, 0),
            juce::Justification::centredLeft, 1);

        const float side = juce::jmax(40.0f,
            juce::jmin(bounds.getWidth() - 16.0f, bounds.getHeight() - 38.0f));
        const float radius = side * 0.42f;
        const float cx = bounds.getCentreX();
        const float cy = bounds.getY() + 28.0f
            + (bounds.getHeight() - 34.0f) * 0.5f;
        graphics.setColour(colour(palette::line).withAlpha(0.62f));
        graphics.drawLine(cx - radius, cy, cx + radius, cy, 0.9f);
        graphics.drawLine(cx, cy - radius, cx, cy + radius, 0.9f);
        graphics.drawEllipse(cx - radius, cy - radius,
            radius * 2.0f, radius * 2.0f, 0.9f);

        juce::Path path;
        juce::Path travelled;
        constexpr int samples = 360;
        const int last = juce::jlimit(0, samples,
            static_cast<int>(std::floor(progress * samples)));
        juce::Point<float> cursor(cx, cy);
        const bool rolling = curve == GeometryCurve::cycloid
            || curve == GeometryCurve::curtateTrochoid
            || curve == GeometryCurve::prolateTrochoid;
        for (int i = 0; i <= samples; ++i) {
            const double t = static_cast<double>(i) / samples;
            Point2D point{};
            if (!geometryCurvePoint(curve, t, cycles, 0.0, terms, point,
                                    billiardPattern, lissajous))
                continue;
            const float x = cx + static_cast<float>(point.x) * radius;
            const float y = cy - static_cast<float>(point.y) * radius;
            const bool newRoll = rolling && i > 0
                && std::floor(t * cycles + 1.0e-10)
                    > std::floor((t - 1.0 / samples) * cycles + 1.0e-10);
            if (i == 0 || newRoll)
                path.startNewSubPath(x, y);
            else
                path.lineTo(x, y);
            if (i <= last) {
                if (i == 0 || newRoll)
                    travelled.startNewSubPath(x, y);
                else
                    travelled.lineTo(x, y);
            }
            if (i == last)
                cursor = {x, y};
        }
        graphics.setColour(colour(palette::voiceTwo).withAlpha(0.35f));
        graphics.strokePath(path, juce::PathStrokeType(1.3f));
        graphics.setColour(colour(palette::voiceTwo));
        graphics.strokePath(travelled, juce::PathStrokeType(2.0f));
        graphics.fillEllipse(cursor.x - 3.5f, cursor.y - 3.5f, 7.0f, 7.0f);
    }

    static void drawPatternField(juce::Graphics& graphics,
                                 const juce::Rectangle<float> bounds,
                                 const CompositionRecipe& recipe,
                                 const EventPlan& plan,
                                 const double progress,
                                 const std::size_t formalCycle,
                                 const double formalPhaseAmount,
                                 const UiLanguage language,
                                 const IntensityLaw law,
                                 const IntensityLaw lawB,
                                 const float blend,
                                 const float amount,
                                 const std::size_t visibleVoiceCount,
                                 const bool developmentEnabled,
                                 const std::uint32_t developmentSeed,
                                 const std::uint64_t passage) {
        graphics.setColour(colour(palette::soft));
        graphics.setFont(monoFont(10.5f));
        const bool compact = bounds.getWidth() < 230.0f;
        const auto title = compact
            ? recipe.patternMode == PatternMode::unrestricted
                ? localized(language, "CAMPO ABERTO", "OPEN FIELD", "CHAMP LIBRE")
                : recipe.patternMode == PatternMode::adhesivePads
                    ? localized(language, "ILHAS MÓVEIS", "MOVING PADS", "ÎLOTS MOBILES")
                    : localized(language, "MICROLINHAS", "MICROLANES", "MICROLIGNES")
            : recipe.patternMode == PatternMode::unrestricted
            ? localized(language, "CAMPO ABERTO / LUPA MÓVEL",
                        "OPEN FIELD / MOVING FOCUS", "CHAMP LIBRE / LOUPE MOBILE")
            : recipe.patternMode == PatternMode::adhesivePads
                ? localized(language, "ILHAS MÓVEIS / ANALOGIA",
                            "MOVING PADS / ANALOGY", "ÎLOTS MOBILES / ANALOGIE")
                : localized(language, "MICROLINHAS MÓVEIS / ANALOGIA",
                            "MOVING DIAGONAL MICROLANES / ANALOGY",
                            "MICROLIGNES MOBILES / ANALOGIE");
        graphics.drawText(title, bounds.toNearestInt().withHeight(20),
                          juce::Justification::centredLeft);

        const float side = juce::jmax(40.0f,
            juce::jmin(bounds.getHeight() - 28.0f, bounds.getWidth() - 8.0f));
        const juce::Rectangle<float> square(bounds.getCentreX() - side * 0.5f,
                                             bounds.getY() + 24.0f,
                                             side, side);
        const auto pointAt = [&](const float x, const float y) {
            return juce::Point<float>(square.getCentreX() + x * side * 0.5f,
                                      square.getCentreY() - y * side * 0.5f);
        };

        graphics.setColour(colour(palette::graph));
        graphics.fillRect(square);
        const double sectionIndex = static_cast<double>(passage
            * kFormalCycleCount + formalCycle);
        const double maskClock = sectionIndex + progress;
        const auto maskPose = patternFieldPose(recipe.patternMode, maskClock,
                                               developmentSeed);
        if (recipe.patternMode == PatternMode::adhesivePads) {
            constexpr std::array<juce::Point<float>, 4> centres = {
                juce::Point<float>(0.0f, -0.58f), juce::Point<float>(0.0f, 0.58f),
                juce::Point<float>(-0.58f, 0.0f), juce::Point<float>(0.58f, 0.0f)};
            graphics.setColour(colour(palette::voiceTwo).withAlpha(0.30f));
            const double cosine = std::cos(maskPose.rotationRadians);
            const double sine = std::sin(maskPose.rotationRadians);
            const auto transformPadPoint = [&](const Point2D point) {
                return pointAt(static_cast<float>(cosine * point.x - sine * point.y
                        + maskPose.offsetX),
                    static_cast<float>(sine * point.x + cosine * point.y
                        + maskPose.offsetY));
            };
            for (std::size_t bridgeIndex = 0; bridgeIndex < 4; ++bridgeIndex) {
                const auto bridge = patternFieldPadBridge(maskPose, bridgeIndex);
                if (bridge.radius <= 0.0)
                    continue;
                juce::Path connection;
                const auto start = transformPadPoint(bridge.start);
                const auto end = transformPadPoint(bridge.end);
                connection.startNewSubPath(start);
                connection.lineTo(end);
                const float width = static_cast<float>(bridge.radius) * side;
                graphics.setColour(colour(palette::voiceTwo).withAlpha(0.08f));
                graphics.strokePath(connection, juce::PathStrokeType(width
                    + static_cast<float>(kPatternFieldEdgeSoftness * side)));
                graphics.setColour(colour(palette::voiceTwo).withAlpha(0.19f));
                graphics.strokePath(connection, juce::PathStrokeType(width));
            }
            for (std::size_t organism = 0; organism < centres.size(); ++organism) {
                const auto centre = centres[organism];
                const double organismRadius = patternFieldPadRadius(maskPose,
                                                                      organism);
                juce::Path pad;
                constexpr int perimeterSteps = 48;
                for (int step = 0; step <= perimeterSteps; ++step) {
                    const double angle = kTau * static_cast<double>(step)
                        / static_cast<double>(perimeterSteps);
                    const double unitX = std::cos(angle);
                    const double unitY = std::sin(angle);
                    const double boundary = patternFieldPadBoundary(maskPose, angle,
                                                                      organism);
                    const double localX = static_cast<double>(centre.x)
                        + maskPose.padCentreOffsets[organism].x
                        + organismRadius * boundary * unitX;
                    const double localY = static_cast<double>(centre.y)
                        + maskPose.padCentreOffsets[organism].y
                        + organismRadius * boundary * unitY;
                    const auto p = pointAt(static_cast<float>(cosine * localX
                            - sine * localY + maskPose.offsetX),
                        static_cast<float>(sine * localX + cosine * localY
                            + maskPose.offsetY));
                    if (step == 0)
                        pad.startNewSubPath(p);
                    else
                        pad.lineTo(p);
                }
                pad.closeSubPath();
                const float pulseAlpha = static_cast<float>(0.075
                    + (organismRadius - 0.34) * 0.42);
                graphics.setColour(colour(palette::voiceTwo)
                    .withAlpha(pulseAlpha * 0.8f));
                graphics.strokePath(pad, juce::PathStrokeType(
                    static_cast<float>(kPatternFieldEdgeSoftness * side)));
                graphics.setColour(colour(palette::voiceTwo)
                    .withAlpha(pulseAlpha));
                graphics.fillPath(pad);
                graphics.setColour(colour(palette::voiceTwo).withAlpha(0.64f));
                graphics.strokePath(pad, juce::PathStrokeType(0.8f));
            }
        } else if (recipe.patternMode == PatternMode::diagonalLanes) {
            const double cosine = std::cos(maskPose.rotationRadians);
            const double sine = std::sin(maskPose.rotationRadians);
            const auto transformedPoint = [&](const float x, const float y) {
                return pointAt(static_cast<float>(cosine * x - sine * y
                        + maskPose.offsetX),
                    static_cast<float>(sine * x + cosine * y + maskPose.offsetY));
            };
            for (std::size_t laneIndex = 0; laneIndex < 2; ++laneIndex) {
                const float direction = laneIndex == 0 ? 1.0f : -1.0f;
                juce::Path lane;
                constexpr int curveSteps = 64;
                for (int step = 0; step <= curveSteps; ++step) {
                    const float x = -1.0f + 2.0f * static_cast<float>(step)
                        / static_cast<float>(curveSteps);
                    const float displacement = static_cast<float>(
                        patternFieldLaneDisplacement(maskPose, x));
                    const float y = direction * (0.55f * x + displacement)
                        + static_cast<float>(maskPose.laneCentreOffsets[laneIndex]);
                    const auto p = transformedPoint(x, y);
                    if (step == 0)
                        lane.startNewSubPath(p);
                    else
                        lane.lineTo(p);
                }
                const float stroke = static_cast<float>(
                    maskPose.laneHalfWidths[laneIndex]) * side;
                graphics.setColour(colour(palette::voiceTwo).withAlpha(0.09f));
                graphics.strokePath(lane, juce::PathStrokeType(stroke
                    + static_cast<float>(kPatternFieldEdgeSoftness * side)));
                graphics.setColour(colour(palette::voiceTwo).withAlpha(0.30f));
                graphics.strokePath(lane, juce::PathStrokeType(stroke));
            }
        } else {
            const auto focus = pointAt(static_cast<float>(maskPose.focusX),
                                       static_cast<float>(maskPose.focusY));
            const float radius = side * static_cast<float>(maskPose.focusRadius) * 0.5f;
            graphics.setColour(colour(palette::voiceTwo).withAlpha(0.12f));
            graphics.fillEllipse(focus.x - radius, focus.y - radius,
                                 radius * 2.0f, radius * 2.0f);
            graphics.setColour(colour(palette::voiceTwo).withAlpha(0.68f));
            graphics.drawEllipse(focus.x - radius, focus.y - radius,
                                 radius * 2.0f, radius * 2.0f, 1.3f);
            graphics.setColour(colour(palette::voiceTwo));
            graphics.fillEllipse(focus.x - 3.5f, focus.y - 3.5f, 7.0f, 7.0f);
        }

        graphics.setColour(colour(palette::line));
        graphics.drawRect(square, 1.0f);
        graphics.drawLine(square.getCentreX(), square.getY(),
                          square.getCentreX(), square.getBottom(), 0.8f);
        graphics.drawLine(square.getX(), square.getCentreY(),
                          square.getRight(), square.getCentreY(), 0.8f);

        std::array<juce::Colour, kMaxVoices> tints{};
        for (std::size_t voice = 0; voice < tints.size(); ++voice)
            tints[voice] = voiceTint(voice);
        const auto [phaseOffset, phaseSlope] =
            formalPhaseArcForDrawing(formalCycle, formalPhaseAmount);
        const double xCycles = recipe.voices[0].cyclesPerSection;
        const double yCycles = recipe.voices[1].cyclesPerSection + phaseSlope;
        const double xPhase = recipe.voices[0].phaseCycles;
        const double yPhase = recipe.voices[1].phaseCycles + phaseOffset;
        const auto fieldPointAt = [&](const double t) {
            return pointAt(static_cast<float>(std::sin(kTau * (xCycles * t + xPhase))),
                           static_cast<float>(std::sin(kTau * (yCycles * t + yPhase))));
        };
        juce::Path fullPath;
        juce::Path tracedPath;
        constexpr int samples = 512;
        const int last = juce::jlimit(0, samples,
            static_cast<int>(std::floor(progress * samples)));
        for (int i = 0; i <= samples; ++i) {
            const double t = static_cast<double>(i) / samples;
            const auto p = fieldPointAt(t);
            if (i == 0)
                fullPath.startNewSubPath(p);
            else
                fullPath.lineTo(p);
            if (i <= last) {
                if (i == 0)
                    tracedPath.startNewSubPath(p);
                else
                    tracedPath.lineTo(p);
            }
        }
        graphics.setColour(colour(palette::ink).withAlpha(0.24f));
        graphics.strokePath(fullPath, juce::PathStrokeType(1.1f));
        graphics.setColour(colour(palette::ink));
        graphics.strokePath(tracedPath, juce::PathStrokeType(1.8f));

        // A short, fading tail gives direction and local speed context while
        // staying on the exact phase arc used by this formal cycle.
        const double fastestCycle = juce::jmax(0.5, std::max(xCycles, yCycles));
        const double tailSpan = std::min(0.14, 0.5 / fastestCycle);
        const double tailStart = std::max(0.0, progress - tailSpan);
        constexpr int tailSegments = 18;
        auto previousTrailPoint = fieldPointAt(tailStart);
        for (int segment = 1; segment <= tailSegments; ++segment) {
            const double fraction = static_cast<double>(segment) / tailSegments;
            const auto trailPoint = fieldPointAt(tailStart
                + (progress - tailStart) * fraction);
            const float age = static_cast<float>(fraction);
            graphics.setColour(colour(palette::voiceTwo).withAlpha(0.08f + 0.52f * age));
            graphics.drawLine(previousTrailPoint.x, previousTrailPoint.y,
                trailPoint.x, trailPoint.y, 0.7f + 1.2f * age);
            previousTrailPoint = trailPoint;
        }

        for (const auto& event : plan.events) {
            if (event.voice >= visibleVoiceCount)
                continue;
            const double eventProgress = event.timeSeconds / recipe.sectionSeconds;
            if (!patternFieldAllows(recipe.patternMode, event.fieldX,
                                    event.fieldY, sectionIndex + eventProgress,
                                    developmentSeed))
                continue;
            const auto p = pointAt(event.fieldX, event.fieldY);
            const float development = developmentEnabled
                ? passageEventWeight(developmentSeed, passage, event.voice,
                    eventProgress) : 1.0f;
            const float radius = 2.0f
                + 2.8f * eventIntensity(event.fieldX, event.fieldY, law,
                    lawB, blend, amount, recipe)
                    * development * patternFieldWeight(recipe.patternMode,
                        event.fieldX, event.fieldY, sectionIndex + eventProgress,
                        developmentSeed);
            graphics.setColour(tints[event.voice % tints.size()].withAlpha(0.92f));
            if (development <= 0.0f) {
                graphics.drawLine(p.x - 3.0f, p.y - 3.0f, p.x + 3.0f, p.y + 3.0f);
                graphics.drawLine(p.x - 3.0f, p.y + 3.0f, p.x + 3.0f, p.y - 3.0f);
            } else {
                graphics.fillEllipse(p.x - radius, p.y - radius,
                                     radius * 2.0f, radius * 2.0f);
            }
        }
        const auto pen = fieldPointAt(progress);
        const float penNormalizedX = static_cast<float>(
            (pen.x - square.getCentreX()) / (side * 0.5f));
        const float penNormalizedY = static_cast<float>(
            (square.getCentreY() - pen.y) / (side * 0.5f));
        const auto xProjection = pointAt(penNormalizedX, 0.0f);
        const auto yProjection = pointAt(0.0f, penNormalizedY);
        const auto drawProjection = [&graphics](const juce::Point<float> from,
                                                const juce::Point<float> to) {
            constexpr int dashCount = 5;
            for (int dash = 0; dash < dashCount; ++dash) {
                const float start = static_cast<float>(dash) / dashCount;
                const float end = std::min(1.0f, start + 0.11f);
                graphics.drawLine(from.x + (to.x - from.x) * start,
                    from.y + (to.y - from.y) * start,
                    from.x + (to.x - from.x) * end,
                    from.y + (to.y - from.y) * end, 0.8f);
            }
        };
        graphics.setColour(colour(palette::soft).withAlpha(0.60f));
        drawProjection(pen, xProjection);
        drawProjection(pen, yProjection);
        graphics.setColour(colour(palette::voiceOne));
        graphics.fillEllipse(xProjection.x - 2.6f, square.getCentreY() - 2.6f, 5.2f, 5.2f);
        graphics.setColour(colour(palette::voiceTwo));
        graphics.fillEllipse(square.getCentreX() - 2.6f, yProjection.y - 2.6f, 5.2f, 5.2f);

        const double phaseX = kTau * (xCycles * progress + xPhase);
        const double phaseY = kTau * (yCycles * progress + yPhase);
        const double velocityX = kTau * xCycles * std::cos(phaseX);
        const double velocityY = kTau * yCycles * std::cos(phaseY);
        const double speed = std::hypot(velocityX, velocityY);
        if (speed > 1.0e-9) {
            const float vectorLength = side * 0.075f;
            const juce::Point<float> tip(
                pen.x + vectorLength * static_cast<float>(velocityX / speed),
                pen.y - vectorLength * static_cast<float>(velocityY / speed));
            graphics.setColour(colour(palette::ink).withAlpha(0.85f));
            graphics.drawLine(pen.x, pen.y, tip.x, tip.y, 1.5f);
            const float angle = std::atan2(tip.y - pen.y, tip.x - pen.x);
            graphics.drawLine(tip.x, tip.y,
                tip.x - 5.0f * std::cos(angle - 0.55f),
                tip.y - 5.0f * std::sin(angle - 0.55f), 1.5f);
            graphics.drawLine(tip.x, tip.y,
                tip.x - 5.0f * std::cos(angle + 0.55f),
                tip.y - 5.0f * std::sin(angle + 0.55f), 1.5f);
        }
        graphics.setColour(colour(palette::voiceOne));
        graphics.drawEllipse(pen.x - 6.5f, pen.y - 6.5f, 13.0f, 13.0f, 1.7f);
        graphics.fillEllipse(pen.x - 2.5f, pen.y - 2.5f, 5.0f, 5.0f);
    }

